'use strict';
(() => {
const D=globalThis.RA.D;
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='word-choice')=>({wrong,right,reason,errorType});
const Q=(s,prompt,answer,wrong1,wrong2,explain,errorType='meaning')=>({s,prompt,answer,wrong1,wrong2,explain,errorType});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline: https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,contexts,mistake,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(contexts)?contexts:[contexts],mistakes:[mistake],quiz:qs.map((q,i)=>({id:`${w}.q${i+1}`,senseId:`${w}.s${q.s}`,prompt:q.prompt,answer:q.answer,options:[q.answer,q.wrong1,q.wrong2],explain:q.explain,errorType:q.errorType,type:'辨义与用法'}))});
P('purism','From French purisme, formed from pur “pure”; the term names strict resistance to change or borrowing, especially in language and art.',C('purism.s1','语言','The editor’s purism led her to reject every recent loanword.','编辑的纯正主义使她拒绝了所有新近借入的词。','linguistic purism','名词，指坚持语言、艺术等应保持纯粹而排斥混合或变化的态度。','rejection of all borrowings exemplifies linguistic purism.','语言'),M('His purism welcomed every new spelling and foreign loan without restriction.','His purism rejected new spellings and foreign loans.','purism 是排斥混合或变化的严格立场，不是无条件接纳新形式。','meaning'),[Q(1,'A critic of linguistic purism would object to…','insisting that borrowed words must never enter a language','allowing speakers to borrow words','recording how a word is pronounced','Purism is strict opposition to linguistic change or borrowing.','meaning'),Q(1,'What is being described by “purism in painting”?','a strict preference for an unmixed or traditional style','a method for pricing paintings','a type of paintbrush','The word extends beyond language to strict aesthetic principles.','context'),Q(1,'Which phrase naturally uses purism?','a movement of linguistic purism','a purism of three kilometers','purism the package tomorrow','Purism is a noun for an ideology or strict attitude.','grammar'),Q(1,'If a style rejects outside influences to remain “pure,” it reflects…','purism','proximity','provision','Purism centers on preserving an idealized purity against outside mixture.','meaning')]);
P('purist','From purism/pure + -ist; purism derives from French purisme. A purist demands traditional or unmixed correctness.',C('purist.s1','通用','The grammar purist objected to ending the sentence with a preposition.','这位语法纯正论者反对把句子以介词结尾。','a purist about/in + field','名词，指坚持严格传统标准、反感变通的人。','the speaker insists on a strict usage rule.','语言'),M('The purist happily accepted every stylistic compromise and rejected no changes.','The purist resisted stylistic compromises and insisted on traditional standards.','不拒绝任何变化与 purist 所代表的严格守旧立场相矛盾。','meaning'),[Q(1,'A musical purist is most likely to…','insist that a genre keep its traditional sound','ask every musician to change genres','measure the volume of every instrument','A purist demands fidelity to an unaltered or traditional form.','context'),Q(1,'Which phrase is natural?','a purist about pronunciation','a purist to a bus','a purist three minutes','Purist can be followed by about to identify the subject of strict standards.','collocation'),Q(1,'A purist differs from a casual fan because the purist…','is strict about rules or tradition','never has an opinion','owns every instrument','Purists demand strict adherence to particular standards.','meaning'),Q(1,'Which word names a person who supports purism?','purist','purity','purplish','Purist is the person noun formed from purism.','word-formation')]);
P('puritan','From Puritan, the historical name for English Protestants seeking to “purify” the Church of England; it also describes a morally severe person.',[C('puritan.s1','宗教','The museum exhibit explains why English Puritans sought simpler forms of worship.','博物馆展览介绍了英国清教徒为何追求更简朴的礼拜形式。','English/American Puritans','历史上指十六、十七世纪要求改革英国国教的基督新教徒；也可指严苛的人。','historical group advocates simpler worship.','宗教'),C('puritan.s1','社会','Her uncle was a puritan about television and banned every comedy show.','她叔叔对电视节目十分拘谨，禁止播放所有喜剧。','a puritan about + pleasure/activity','引申指对娱乐、享乐等持严苛态度的人。','ban on all comedy signals moral strictness.','社会')],M('The Puritan praised elaborate ceremonies and rejected simpler worship as a goal.','The Puritan favored simpler worship and criticized elaborate ceremonies.','历史上的清教徒倾向改革仪式、追求简朴礼拜；错误句倒置了这一核心特点。','meaning'),[Q(1,'In its historical sense, a Puritan was associated with…','a Protestant reform movement seeking to purify worship','the invention of the printing press','a group of Roman emperors','Puritans were English Protestants seeking further church reform.','meaning'),Q(1,'Calling someone a puritan about movies suggests that person…','is unusually strict about what entertainment is acceptable','collects movie tickets','writes film reviews for a living','The figurative sense refers to moral strictness about pleasure.','context'),Q(1,'Which phrase fits the historical sense?','the Puritan movement in seventeenth-century England','a Puritan recipe for modern cinema','a Puritan unit of distance','The word names a historical Protestant group.','context'),Q(1,'A “puritan about dancing” is likely to…','disapprove of dancing on moral grounds','teach every dance style','have no view about dancing','The figurative usage implies strict disapproval of pleasures.','meaning')]);
P('puritanical','From Puritan + -ical; Puritan is the historical name of a Protestant reform group. Puritanical describes unusually strict disapproval of pleasure.',C('puritanical.s1','社会','The school’s puritanical rules prohibited music, games, and bright clothes.','学校清教式严苛的规定禁止音乐、游戏和鲜艳衣物。','puritanical attitude/rules','形容词，常带批评意味，指对享乐或自由极端拘谨。','broad bans show severe moral strictness.','社会'),M('The puritanical club encouraged unrestricted partying and celebrated every indulgence.','The permissive club encouraged unrestricted partying and celebrated every indulgence.','纵情享乐与 puritanical 的严苛禁欲立场相反。','meaning'),[Q(1,'A puritanical rule about entertainment would likely…','severely restrict what people may watch or enjoy','encourage every form of amusement','set the price of movie tickets','Puritanical means morally strict, especially toward pleasure.','meaning'),Q(1,'Which noun commonly follows puritanical?','attitude','proton','quay','Puritanical commonly modifies attitude, outlook, or rules.','collocation'),Q(1,'A reviewer calls a policy puritanical because it bans harmless dancing. The reviewer thinks it is…','excessively strict about pleasure','carefully measured','scientifically uncertain','The adjective often criticizes undue moral severity.','context'),Q(1,'Which is the closest opposite of puritanical?','permissive','austere','strict','Permissive allows freedoms that a puritanical outlook would restrict.','distinction')]);
P('puritanism','From Puritan + -ism; it can denote Puritan religious beliefs or a broader severe moral attitude opposed to pleasure.',[C('puritanism.s1','宗教','The lecture traces Puritanism from English church reform to settlements in New England.','讲座追溯了清教主义从英国教会改革到新英格兰殖民地的发展。','history/doctrine of Puritanism','指历史上的清教信仰、教义和运动。','lecture follows religious movement.','宗教'),C('puritanism.s1','社会','The critic objected to a new puritanism that treated every pleasure as immoral.','评论者反对一种把所有享乐都视为不道德的新式清规主义。','a strain of puritanism','引申指过分严苛、排斥享乐的道德风气。','condemning all pleasure indicates figurative sense.','社会')],M('The novel attacks puritanism by celebrating every pleasure and rejecting strict morality.','The novel attacks puritanism by portraying its strict moral rules as oppressive.','单纯赞美享乐并不能表达对 puritanism 的批评；需指出其严苛道德约束。','meaning'),[Q(1,'A history of Puritanism would mainly discuss…','a Protestant religious movement and its beliefs','the chemistry of purple pigment','the structure of a pyramid','Puritanism names the religious tradition associated with the Puritans.','context'),Q(1,'In a figurative argument, “modern puritanism” may mean…','an excessively strict attitude toward pleasure','a new scientific measurement system','a form of political geography','The term can broaden to moral severity that condemns enjoyment.','meaning'),Q(1,'Which phrase is natural?','the influence of Puritanism','Puritanism into a pocket','a Puritanism weighs two quarts','The noun names a movement or outlook and can be the object of “influence.”','grammar'),Q(1,'A writer links Puritanism to bans on theater and dancing. What is emphasized?','its strict moral outlook','its theories of astronomy','its use as a liquid unit','Puritanism is associated with religious reform and, figuratively, strict morality.','meaning')]);
P('purity','From Old French pureté, from Latin puritas “cleanliness,” based on purus “pure”; purity can be physical cleanliness or moral innocence.',[C('purity.s1','通用','The laboratory tested the purity of the drinking water.','实验室检测了饮用水的纯度。','purity of + substance','指物质不含污染物、杂质的状态。','water is evaluated for contaminants.','科学'),C('purity.s2','通用','The poem praises the purity of her intentions.','这首诗赞美她意图的纯洁。','purity of heart/intentions','引申指品德或意图不含邪念、不道德因素。','moral intention rather than material substance.','通用')],M('The purity of the sample was high because it contained many unknown contaminants.','The purity of the sample was low because it contained many unknown contaminants.','大量污染物表示纯度低而非高。','meaning'),[Q(1,'A chemist measures a sample’s purity. What is being checked?','how free it is from unwanted substances','how purple it looks','how quickly it can be pushed','Purity of a material concerns freedom from contaminants or mixture.','meaning'),Q(2,'“Purity of intention” concerns…','whether a person’s motives are morally sincere','the chemical composition of water','the person’s job qualification','Sense 2 concerns moral innocence or sincerity.','context'),Q(1,'Which phrase is idiomatic?','purity of the metal','purity into a quarrel','purity from a quarter','Purity of a substance is a natural phrase for its cleanliness or composition.','collocation'),Q(1,'A water sample contains no pollutants. Its purity is…','high','questionable by definition','a measure of its color only','Freedom from contaminants indicates high purity.','meaning')]);
P('purple','From Old English purpul, from Latin purpura and Greek porphyra, the name of a costly purple dye; it means the color or having that color.',[C('purple.s1','色彩','She wore a purple scarf with a dark coat.','她穿深色外套，配了一条紫色围巾。','purple + noun','形容词，表示红蓝之间的颜色。','scarf has the named hue.','色彩'),C('purple.s2','色彩','A deep purple filled the evening sky after sunset.','日落后，深紫色铺满了夜空。','a shade of purple','名词，指紫色这种颜色。','purple is used as a color noun.','色彩')],M('The ripe orange was purple, bright green, and had no orange color at all.','The ripe orange was orange, bright and evenly colored.','若物体呈紫色，应称 purple orange；原句把互不相同的颜色断定同时成立而自相矛盾。','meaning'),[Q(1,'A purple flower has what color?','a hue between red and blue','pure yellow','transparent like glass','Purple is the color formed by red and blue hues.','meaning'),Q(2,'In “She chose a purple for the walls,” purple is…','a noun naming a color','a verb meaning to push','an adjective modifying a verb','Purple can be a noun for the color itself.','grammar'),Q(1,'Which collocation is natural?','a purple dress','a purple loudly','purple to a meeting','Purple commonly modifies a color-bearing object such as a dress.','collocation'),Q(1,'Which statement uses purple figuratively in the color sense?','The bruise turned purple overnight.','The committee purpled the proposal.','The purple of the law prosecuted him.','Bruises can literally become purple in color.','context')]);
P('purplish','From purple + -ish, where -ish means “somewhat”; it describes a color approaching purple without being fully purple.',C('purplish.s1','通用','The clouds took on a purplish tint as the sun went down.','太阳落山时，云层泛起了紫色。','purplish tint/shade','形容词，表示带紫色、略紫，而非纯紫色。','tint is close to but not exactly purple.','色彩'),M('The purplish paint was perfectly pure white with no trace of violet.','The purplish paint was a pale shade with a violet cast.','纯白且无紫调不应描述为 purplish。','meaning'),[Q(1,'A purplish wall is…','somewhat purple in color','exactly colorless','definitely bright orange','The suffix -ish indicates a color that is somewhat purple.','meaning'),Q(1,'Which phrase is natural?','a purplish glow','a purplish under a chair','purplish to measure','Purplish can modify a visible light, tint, or shade.','collocation'),Q(1,'Why might an artist call a cloud purplish rather than purple?','Its color has a slight purple cast but is not pure purple.','The cloud is a noun rather than an adjective.','The cloud has no color whatsoever.','-ish signals approximation or a slight quality.','meaning'),Q(1,'Choose the correct related form: “The fabric looked ___ in the dim light.”','purplish','purplishnessly','purplingly','Purplish is the adjective meaning somewhat purple.','word-formation')]);
P('purport','From Anglo-French purporter, from Latin proportare “carry forward”; as a verb it claims or appears to mean, often with doubt, and as a noun it is apparent meaning.',[C('purport.s1','书面','The letter purports to be from the city council, but its address is fake.','这封信声称来自市议会，但地址是假的。','purport to be/do','动词，表示声称或自称，常暗示真实性可疑。','claim is explicitly doubted.','书面'),C('purport.s1','书面','The purport of the notice is that residents must leave by noon.','通知的大意是居民必须在中午前离开。','the purport of + text','名词，指文字表面表达的主旨或意图。','sentence summarizes the notice’s apparent meaning.','书面')],M('The fake email purports from the bank to request your password.','The fake email purports to come from the bank and requests your password.','purport 作动词通常用 purport to be/do，不接 purports from 的结构。','grammar'),[Q(1,'A document that purports to be official…','claims or appears to be official, perhaps falsely','has been proven official beyond doubt','is necessarily written by a lawyer','Purport to be often reports a claim while leaving authenticity uncertain.','meaning'),Q(1,'Which phrase correctly uses the verb?','The message purports to offer a refund.','The message purports offering a refunding.','The message purports from a refund.','The standard construction is purport to do something.','grammar'),Q(1,'The purport of an announcement is…','its apparent meaning or main point','the paper it is printed on','the person who delivered it','Purport as a noun means the apparent meaning or intent of a text.','meaning'),Q(1,'A website purports to cure every illness. Why might a reader be cautious?','Purport can signal a doubtful or unverified claim.','Purport means the website is officially licensed.','Purport is a medical diagnosis.','The verb often implies that a claim is asserted but may not be true.','context')]);
P('purpose','From Old French purpos “intention, aim,” from proposer “put forth”; purpose is an intended goal, a function, or firm resolve.',[C('purpose.s1','通用','The purpose of the survey is to learn how commuters travel.','这项调查的目的是了解通勤者如何出行。','purpose of + noun/to do','名词，指计划做某事的目标或意图。','survey has a stated aim.','通用'),C('purpose.s2','通用','A ruler’s purpose is to measure length.','尺子的用途是测量长度。','purpose of an object','指工具、行动或制度的用途、功能。','explains the ruler’s function.','通用'),C('purpose.s3','书面','She spoke with purpose and finished the difficult task.','她意志坚定地发言，并完成了艰巨任务。','a sense of purpose; with purpose','可指坚定意志或决心。','determined manner signals resolve.','通用')],M('The purpose of the thermometer is to measure distance.','The purpose of the thermometer is to measure temperature.','温度计的功能是测温，不是测量距离。','meaning'),[Q(1,'The purpose of a survey is…','the goal it is intended to achieve','the person who completes it','the paper color of its form','Purpose in sense 1 means the intended aim.','meaning'),Q(2,'What is the purpose of a ruler?','to measure length','to tell the temperature','to store water','Sense 2 means the function an object is designed to serve.','context'),Q(3,'A person who acts with purpose is acting…','with firm intention and resolve','without any plan or motivation','only by accident','Purpose can mean determination or a firm wish to carry out a decision.','meaning'),Q(1,'Which phrase is correct?','the purpose of the meeting','the purpose into the meeting','purpose the meetingly','Purpose of names the aim associated with an event or action.','grammar')]);
P('purposefully','From purposeful + -ly; purpose derives from Old French purpos. The adverb describes determined action with a clear aim.',C('purposefully.s1','通用','She walked purposefully toward the help desk instead of wandering through the lobby.','她坚定地朝服务台走去，没有在大厅里漫无目的地闲逛。','act/walk purposefully','表示动作目标明确、坚定；不只是偶然发生。','direct movement reveals a definite aim.','通用'),M('He purposefully wandered without any destination or intention.','He aimlessly wandered without any destination or intention.','没有目的地的漫游是 aimlessly，不是带有明确目标的 purposefully。','meaning'),[Q(1,'Someone walks purposefully to an office. The movement seems…','directed toward a clear goal','completely random and aimless','caused by a sudden fall','Purposefully means with intention or determination.','meaning'),Q(1,'Which sentence uses purposefully as an adverb?','She purposefully selected the safer route.','She was purposefully of the route.','The purposefully was safer.','The adverb modifies selected and describes how she made the choice.','grammar'),Q(1,'Which is a purposefully chosen action?','setting an alarm to wake up for an exam','accidentally dropping a book','forgetting why one entered a room','A deliberate alarm is chosen to achieve the goal of waking up.','context'),Q(1,'What is the closest contrast to purposefully?','accidentally','deliberately','intentionally','Purposefully means intentionally; accidentally contrasts with it.','distinction')]);
P('purposely','From purpose + -ly; purpose comes through Old French purpos. Purposely means intentionally, rather than by accident.',C('purposely.s1','通用','He purposely left the last chair empty for the guest speaker.','他特意留了最后一把椅子给特邀演讲者。','purposely do something','副词，强调行为出于有意安排。','empty chair was deliberately reserved.','通用'),M('She purposely spilled the water by accident.','She accidentally spilled the water.','purposely 表示有意，by accident 表示意外，二者矛盾。','meaning'),[Q(1,'If a student purposely omits a paragraph, the student…','deliberately leaves it out','forgets it by accident','copies it twice without noticing','Purposely means intentionally.','meaning'),Q(1,'Which phrase is correct?','purposely left the door open','purposely by accident left the door open','purposely from the door open','Purposely modifies the action and marks intention; it conflicts with by accident.','grammar'),Q(1,'A driver purposely slows down near a school. Why?','the driver intends to reduce speed','the driver’s brakes failed by chance','the driver forgot the school was there','Purposefully slowing is a deliberate action.','context'),Q(1,'Choose the closest synonym for purposely.','intentionally','unwittingly','randomly','Purposely is equivalent to intentionally or on purpose.','meaning')]);
P('purse','From Old English purs, from Late Latin bursa “bag,” ultimately Greek byrsa “hide, leather”; it can mean a small money bag, funds, or draw the lips together.',[C('purse.s1','生活','She found her bus card in the front pocket of her purse.','她在手提包前袋里找到了公交卡。','carry/find something in a purse','名词：装钱和随身小物的袋子；英式英语也可指手提包。','personal bag holds the card.','生活'),C('purse.s2','经济','The renovation will depend on the public purse.','这项翻修将取决于公共财政是否有资金。','the public purse; purse strings','名词引申指可用于某目的的资金。','public budget is the available money.','经济'),C('purse.s3','通用','He pursed his lips before answering the difficult question.','回答这个难题前，他先噘起了嘴。','purse one’s lips','动词：把嘴唇紧紧收拢，常表达犹豫或不满。','lips are drawn together.','通用')],M('She put the coins in her purse, which was a verb meaning she tightened her lips.','She put the coins in her purse, a small bag for money.','装硬币的是名词 purse；“噘嘴”是动词 purse，句中不能将两义混用。','distinction'),[Q(1,'In “She searched her purse for the ticket,” what is her purse?','a small bag for personal items','a public budget','a facial expression','Sense 1 is a money bag or handbag.','meaning'),Q(2,'“The project strained the public purse” means it strained…','public funds','a leather bag','the lips of a public official','The figurative financial sense is the available public money.','meaning'),Q(3,'To purse one’s lips is to…','draw the lips tightly together','open the mouth widely','put money into a bag','As a verb, purse describes tightening or puckering the lips.','meaning'),Q(1,'Which sentence uses purse as a verb?','He pursed his lips in doubt.','She lost her purse on the bus.','The public purse was limited.','The first has purse taking lips as its object, showing the verb sense.','grammar')]);
P('pursue','From Old French pursuer, from Latin prosequi “follow after”; pursue means chase, work toward a goal/career, or continue a line of inquiry.',[C('pursue.s1','通用','The ranger pursued the injured deer to guide it away from the road.','护林员追赶那只受伤的鹿，想把它引离公路。','pursue a person/animal','追逐、追赶以抓住或跟上目标。','ranger follows the deer.','通用'),C('pursue.s2','通用','After graduation, Nia pursued a career in public health.','毕业后，妮娅投身公共卫生事业。','pursue a goal/career/degree','努力实现目标或从事某职业。','career is a long-term aim.','职业'),C('pursue.s3','书面','The journalist pursued the unanswered question for months.','记者数月来持续追查这个未解问题。','pursue an inquiry/topic','继续探讨、追究一个问题或行动。','journalist continues investigation.','书面')],M('She pursued a degree by abandoning every class and refusing to complete assignments.','She pursued a degree by attending classes and completing assignments.','努力取得学位与放弃课程、不完成作业相矛盾。','meaning'),[Q(1,'A police officer pursues a suspect. What is the officer doing?','following in order to catch the suspect','helping the suspect escape','writing the suspect a degree','Sense 1 means chase or follow to catch.','meaning'),Q(2,'To pursue a career in medicine is to…','work toward entering or succeeding in that profession','run away from every medical job','ask a doctor to chase you','Pursue a career means seek it over time through effort.','meaning'),Q(3,'A reporter pursues a story by…','continuing to investigate it','publishing a blank page','ending the inquiry immediately','The extended sense is continue investigating or following a topic.','context'),Q(1,'Which pattern is correct?','pursue a goal','pursue to a goal','pursue for a goal','Pursue is transitive and takes its goal directly.','grammar')]);
P('pursuit','From pursue + -t, from Old French pursuer and Latin prosequi “follow after”; pursuit is chasing or striving to achieve something.',C('pursuit.s1','通用','The pursuit of a safer battery kept the research team busy for years.','对更安全电池的追求让研究团队忙碌了多年。','the pursuit of + goal; in pursuit of','名词，指追求目标或追赶对象的过程。','research effort aims for a goal.','通用'),M('The pursuit of the fleeing thief ended because nobody chased or searched for him.','The pursuit of the fleeing thief continued as officers chased him.','若没人追赶或搜寻，就不存在对逃犯的 pursuit。','meaning'),[Q(1,'The pursuit of knowledge means…','the effort to gain knowledge','knowledge chasing a person','the refusal to study','Pursuit can mean the act of trying to achieve or obtain something.','meaning'),Q(1,'Which phrase is natural?','in pursuit of a suspect','at pursuit to suspect','pursuit with a suspectly','In pursuit of someone means while trying to catch that person.','collocation'),Q(1,'A high-speed pursuit involves…','a chase','a quiet classroom discussion','a measurement of purple dye','Pursuit can name the act of chasing a person or vehicle.','context'),Q(1,'Which phrase uses pursuit for an aim rather than a chase?','the pursuit of happiness','the pursuit of the escaped horse','a pursuit down the road','Pursuit of happiness is striving toward a goal, not following a fleeing target.','distinction')]);
P('purvey','From Anglo-French purveier, from Latin providere “foresee, provide”; the formal verb means supply goods, services, or information regularly.',C('purvey.s1','商业','The small firm purveys fresh vegetables to three local restaurants.','这家小公司向当地三家餐馆供应新鲜蔬菜。','purvey goods/services to + customer','正式动词，指作为供应商持续提供商品或服务。','firm supplies regular food deliveries.','商业'),M('The restaurant purveys the vegetables by buying them once for its own kitchen, but supplies none to customers.','The wholesaler purveys vegetables to the restaurant.','purvey 表示向他方供应，单纯为自用购买不是供应行为。','meaning'),[Q(1,'A company that purveys food to hotels…','supplies food to them regularly','prosecutes their chefs','measures their dining rooms','Purvey means provide or supply, especially as a business.','meaning'),Q(1,'Which sentence uses purvey correctly?','The agency purveys travel information to visitors.','The agency purveys visitors into a hotel.','The information purveys the agency.','Purvey takes the goods or information supplied as object and recipients may follow to.','grammar'),Q(1,'A news service purveys updates. What does it do?','provides updates to an audience','hides updates from everyone','changes updates into a quarrel','Purvey can mean supply information or news.','context'),Q(1,'Purvey is most similar to which verb?','supply','prohibit','puzzle','Purvey means supply or provide.','meaning')]);
P('push','From Old French pousser, from Latin pulsare “beat, push”; it means exert force, urge someone, or make a determined effort.',[C('push.s1','通用','Push the door gently; it opens toward the corridor.','轻推这扇门，它朝走廊方向打开。','push something open/away','及物动词，用力使物体远离自己或移到新位置。','force moves door outward.','通用'),C('push.s2','通用','The coach pushed the team to keep practicing after the loss.','失利后，教练督促球队继续训练。','push someone to do something','劝促、施压或鼓励某人付出更多努力。','coach urges further effort.','通用'),C('push.s3','通用','The final push to finish the bridge began in May.','五月开始了完成这座桥的最后冲刺。','a push for/toward + goal','名词：推的动作或为达成目标所作的集中努力。','team’s final concentrated effort.','通用')],M('Push the door toward yourself to make it move away from your body.','Pull the door toward yourself to bring it closer.','朝自己方向用力是 pull，不是 push；push 通常使物体远离施力者。','confusable'),[Q(1,'If a sign says PUSH, what should you do to the door?','apply force to move it away from you','pull it toward you','wait for it to open by itself','Push moves something away from the person applying force.','meaning'),Q(2,'A coach pushes an athlete to practice means the coach…','urges the athlete to make more effort','physically removes the athlete from the team','pays for the athlete’s shoes','Push can mean encourage or pressure someone to do more.','meaning'),Q(3,'“A final push to meet the deadline” is…','a last concentrated effort','a device used to measure time','a reason to abandon the project','Push as a noun can mean a determined effort toward a goal.','context'),Q(1,'Which opposite matches the physical verb push?','pull','propel','press','Pull usually draws something toward the person, opposite the away-motion of push.','distinction')]);
P('pushy','From push + -y; push is from Old French pousser. Pushy describes someone too forceful or insistent, often ignoring other people’s wishes.',C('pushy.s1','口语','The pushy salesperson kept interrupting customers who wanted time to compare prices.','这位咄咄逼人的销售员不断打断想要比较价格的顾客。','pushy salesperson/person','口语贬义形容词，指强行推销或不顾他人意愿地坚持。','interruptions disregard customer preference.','口语'),M('The considerate clerk was pushy because she listened quietly and never urged anyone to buy.','The considerate clerk was not pushy because she listened quietly and never urged anyone to buy.','耐心倾听且不施压不符合 pushy 的含义。','meaning'),[Q(1,'A pushy salesperson is likely to…','pressure customers after they ask for space','wait politely while customers decide','avoid discussing any product','Pushy means overly forceful or insistent.','meaning'),Q(1,'Which phrase is natural?','a pushy colleague','a pushy of yesterday','pushy to a measurement','Pushy commonly modifies a person, salesperson, or behavior.','collocation'),Q(1,'Why might someone dislike a pushy fundraiser?','The fundraiser ignores refusals and keeps pressing.','The fundraiser gives people plenty of time and space.','The fundraiser has a colorful poster.','The adjective implies intrusive pressure or insistence.','context'),Q(1,'Which is the closest opposite of pushy?','considerate','insistent','aggressive','Considerate behavior respects others’ wishes, unlike pushy behavior.','distinction')]);
P('put','From Middle English putten; the deeper origin is uncertain, so avoid assigning a confident root. The verb means place, cause a state, express, or submit an idea.',[C('put.s1','通用','Put the keys on the hook beside the door.','把钥匙放在门旁的挂钩上。','put something in/on/at + place','及物动词，表示将某物放置在某处。','keys are moved to a location.','通用'),C('put.s2','通用','The surprise put the children in a cheerful mood.','这个惊喜让孩子们心情愉快。','put someone in + state','使某人或某物处于某种状态。','event causes an emotional state.','通用'),C('put.s3','通用','How would you put your concern in one sentence?','你会如何用一句话表达你的担忧？','put something in words','表示表达或措辞。','speaker expresses an idea.','通用'),C('put.s4','通用','She put a motion to the committee for a vote.','她向委员会提出一项动议供表决。','put a question/motion/request to + group','提交一个观点、请求或议题供他人考虑。','motion is formally submitted.','通用')],M('Put the cup at the shelf so it rests on top of it.','Put the cup on the shelf so it rests on top of it.','物体放在表面上用 on；at 指具体地点但不表达搁置在架子表面。','grammar'),[Q(1,'In “Put the cup on the table,” what does put mean?','place the cup somewhere','describe the cup’s color','ask the cup a question','Put in sense 1 means move an object into a location.','meaning'),Q(2,'“The news put him in a bad mood” means the news…','caused him to be in that state','placed him physically inside a mood','asked him to give a speech','Put can cause someone or something to enter a condition.','meaning'),Q(3,'“I cannot put my worry into words” means I cannot…','express it clearly','place it on a table','submit it to a committee','Put in this expression means formulate or express.','context'),Q(4,'To put a proposal to a committee is to…','submit it for the committee to consider','hide it from the committee','place the committee inside the proposal','Put to a group means present an idea or question for consideration.','meaning')]);
P('put back','From put + back; put is an old English verb of uncertain deeper origin. The phrasal verb means return something to its place or postpone an event.',[C('put back.s1','家居','After using the wrench, put it back in the tool drawer.','用完扳手后，把它放回工具抽屉。','put something back in/on + place','把东西归还原位。','tool returns to its storage place.','家居'),C('put back.s2','商务','Repairs put back the opening of the café by two weeks.','维修使咖啡馆的开业推迟了两周。','put back an event/date by + period','表示延后某个日期或活动。','opening is delayed two weeks.','商务')],M('She put the borrowed book back on the shelf by taking it away to her office permanently.','She put the borrowed book back on the shelf after reading it.','永久带走与“放回原处”矛盾。','meaning'),[Q(1,'After borrowing a screwdriver, you put it back when you…','return it to its usual place','throw it away','delay its manufacture','Put back in sense 1 means return an item to where it belongs.','meaning'),Q(2,'If bad weather puts back a flight, the flight is…','delayed until later','moved to an earlier time','canceled as a legal punishment','Put back can mean postpone an event.','meaning'),Q(1,'Which phrase is correct?','put the files back in the cabinet','put the files back at the cabinet into','put back the cabinet with the files in it','The item is put back in its former location.','grammar'),Q(2,'The meeting was put back by an hour. When will it happen?','one hour later than planned','one hour earlier','at exactly the original time','The phrasal verb means delay, so the meeting moves later.','context')]);
P('put in','From put + in; put is an old English verb of uncertain deeper origin. Put in means invest effort or money, or submit/install something.',[C('put in.s1','商务','Marta put in long hours to finish the safety review.','玛尔塔投入大量时间完成安全审查。','put in time/effort/money','投入时间、精力或资金。','long hours are effort invested.','商务'),C('put in.s2','家居','The electrician put in a new outlet beside the desk.','电工在书桌旁安装了一个新插座。','put in an application/request; put in equipment','可指提交申请，也可指安装某设备。','outlet is installed.','家居')],M('He put in an application by keeping it in a drawer and never sending it.','He put in an application by submitting it to the office.','put in an application 意为提交申请，单纯把它收在抽屉里不算提交。','meaning'),[Q(1,'A student puts in many hours studying. What does put in mean?','spend or invest time','place a student inside a room','submit a court case','Put in time means devote or spend time on an activity.','meaning'),Q(2,'The electrician put in a ceiling fan. The fan was…','installed','delayed','submitted as a question','Put in can mean install equipment.','meaning'),Q(1,'Which phrase is natural?','put in a request','put in a request to be into','put a request in to yesterday','Put in a request means submit it for consideration.','collocation'),Q(1,'Which sentence uses put in to mean effort?','They put in extra work before the launch.','They put in a new window frame.','They put in an application online.','The first refers to effort; the others refer to installation or submission.','distinction')]);
P('put off','From put + off; put is an old English verb of uncertain deeper origin. Put off means postpone, or make someone lose interest or feel dislike.',[C('put off.s1','商务','We put off the inspection until the new parts arrived.','我们把检查推迟到新零件到货后。','put off a meeting/task until + time','推迟某项活动或任务。','inspection moved to a later date.','商务'),C('put off.s2','心理','The restaurant’s dirty tables put us off ordering dessert.','餐馆脏乱的桌子让我们不想点甜点了。','put someone off + noun/gerund','使某人反感、失去兴趣或不愿做某事。','mess discourages ordering.','心理')],M('The broken elevator put off our meeting by making us hold it on the originally scheduled date.','The broken elevator put off our meeting until the next day.','put off 指推迟；若会议仍按原定时间举行就没有推迟。','meaning'),[Q(1,'If the storm puts off a match, the match is…','rescheduled for later','played earlier than planned','made more interesting to watch','Put off in sense 1 means postpone.','meaning'),Q(2,'A rude reply puts a customer off. The customer may…','lose interest or feel discouraged','arrive at the shop earlier','install a new sign','Put off can mean deter or make someone dislike something.','meaning'),Q(1,'Complete: “They put off the trip ___ the roads were repaired.”','until','under','despite to','Put off an event until a later point is a common pattern.','collocation'),Q(2,'The smell put me off my lunch. What happened?','It made me unwilling to eat.','It delayed lunch by two weeks.','It made lunch more delicious.','The phrasal verb here means cause dislike or loss of appetite.','context')]);
P('put out','From put + out; put is of uncertain deeper origin. Put out means extinguish a flame, light, or cigarette.',C('put out.s1','社会','Firefighters put out the kitchen fire before it reached the stairs.','消防员在厨房火势蔓延到楼梯前将火扑灭。','put out a fire/light/cigarette','及物短语动词，指使火焰或灯光熄灭。','fire is extinguished.','社会'),M('The crew put out the fire by adding gasoline until the flames grew higher.','The crew put out the fire by smothering the flames with a fire blanket.','添汽油会助长火势而非扑灭火焰。','meaning'),[Q(1,'To put out a candle is to…','extinguish it','light it for the first time','move it into a box','Put out in this entry means make a flame stop burning.','meaning'),Q(1,'Which object is commonly put out?','a campfire','a printed questionnaire','a legal qualification','Fire, a light, or a cigarette can be put out.','collocation'),Q(1,'The crew put out a small electrical fire. What was the result?','the fire was extinguished','the fire was postponed','the fire became a source of fuel','Put out means extinguish, not delay or supply.','context'),Q(1,'Choose the correct object pattern.','put out the candle','put the candle out of the room to extinguish','put out to the candle','Put out is a separable phrasal verb: put out the candle / put the candle out.','grammar')]);
P('put to death','From put + to + death; put is of uncertain deeper origin. The phrase means kill someone as an official punishment.',C('put to death.s1','法律','The court ordered the captured commander to be put to death after a public trial.','经过公开审判，法院下令处死被俘的指挥官。','be put to death','固定被动表达，指以法定或官方方式处决。','court orders a formal execution.','法律'),M('The judge put the defendant to death by awarding him a community-service award.','The judge put the defendant to death by ordering an execution.','授予社区服务奖不是处决；短语的结果是杀死作为惩罚。','meaning'),[Q(1,'A person sentenced to be put to death is sentenced to…','be executed as a punishment','pay a small parking fine','receive a public commendation','The phrase means kill someone as an official punishment.','meaning'),Q(1,'Which construction is common?','was put to death by the state','was put to death into a pardon','was put death to by trial','The expression is put someone to death, often in the passive be put to death.','grammar'),Q(1,'In a historical text, “the ruler put the captive to death” means the ruler…','ordered or carried out the captive’s execution','released the captive without charge','appointed the captive as a minister','The phrase refers to an official killing as punishment.','meaning'),Q(1,'Which phrase should not be confused with put to death?','put on trial','put an object back','put out a candle','Put on trial means try in court; it does not mean execute.','distinction')]);
P('putrefaction','From Latin putrefacere “make rotten,” from puter “rotten” + facere “make”; putrefaction is decay of organic matter, often with odor and gas.',C('putrefaction.s1','生物','Warm, damp conditions accelerated the putrefaction of the fallen leaves.','温暖潮湿的环境加快了落叶的腐败分解。','putrefaction of organic matter','名词，指细菌等导致的有机物腐败过程。','leaves are decaying in favorable conditions.','生物'),M('The putrefaction preserved the fresh fruit in perfect condition for months.','The refrigeration slowed the putrefaction and kept the fruit fresh.','putrefaction 表示腐败分解，不会保存水果的新鲜状态。','meaning'),[Q(1,'Putrefaction is the process of…','organic matter decaying','metal becoming magnetic','water turning into ice','The term means decay, especially of organic material.','meaning'),Q(1,'Which conditions may speed putrefaction?','warmth and moisture','freezing and drying','a vacuum with no organic matter','Bacteria commonly accelerate decay under warm, damp conditions.','context'),Q(1,'Which phrase is natural?','the putrefaction of dead tissue','putrefaction of a legal clause','a putrefaction of four people','Putrefaction applies to decaying organic matter.','collocation'),Q(1,'A foul odor from rotting food may indicate…','putrefaction','purism','proximity','Putrefaction often produces unpleasant odors as organic matter decays.','meaning')]);
P('putrefy','From Latin putrefacere “make rotten,” from puter “rotten” + facere “make”; the verb means decay or cause organic matter to rot.',C('putrefy.s1','生物','Without refrigeration, the fish began to putrefy within a day.','没有冷藏，这条鱼一天内就开始腐烂。','food/tissue putrefies; cause something to putrefy','可不及物表示腐败，也可及物表示使其腐败。','unrefrigerated fish decays.','生物'),M('The warm storage putrefied the fish, leaving it perfectly fresh and odorless.','The cold storage prevented the fish from putrefying.','腐败后的鱼不会同时保持新鲜无味；冷藏才会减缓腐败。','meaning'),[Q(1,'If meat begins to putrefy, it begins to…','rot','freeze into ice','become sterile metal','Putrefy means decay or become rotten.','meaning'),Q(1,'Which sentence uses putrefy correctly?','Bacteria caused the discarded food to putrefy.','The chef putrefied the recipe by measuring its temperature.','The flowers putrefy into a legal contract.','The verb can take organic matter as the thing that decays.','grammar'),Q(1,'What might stop food from putrefying quickly?','refrigeration','leaving it in warm damp air','adding decaying scraps','Cold storage slows the biological decay process.','context'),Q(1,'How is putrefy related to putrefaction?','putrefy is the verb; putrefaction is the noun for the decay process','putrefy is a color; putrefaction is a bird','they have unrelated meanings','Putrefaction names the process of putrefying.','word-formation')]);
P('putt','From golf putt, perhaps Scots; the verb and noun refer to a short, gentle stroke sending the ball toward the hole on the green.',C('putt.s1','体育','She made a careful putt from the edge of the green and sank the ball.','她从果岭边缘谨慎地轻推一杆，将球打进洞。','make/sink a putt; putt the ball','高尔夫球中在果岭上轻击球使其滚向球洞。','short stroke rolls ball into cup.','体育'),M('He putted the golf ball with a full-power drive from the tee.','He drove the golf ball from the tee, then used a putt on the green.','putt 是果岭上的轻推杆，不是发球台上的全力开球。','distinction'),[Q(1,'Where is a golfer most likely to putt?','on the green near the hole','from a swimming pool','inside the clubhouse kitchen','A putt is a short careful stroke usually played on the green.','context'),Q(1,'To sink a putt means to…','roll the ball into the hole with a short stroke','lift the ball out of the course','measure the length of the golf club','Sinking a putt is successfully putting the ball in the cup.','meaning'),Q(1,'Which phrase is natural?','make a short putt','putt a question to a committee','putt a candle out','Putt is golf terminology, unlike put a question or put out a flame.','collocation'),Q(1,'Which stroke contrasts with a putt from the green?','a drive from the tee','a questionnaire','a legal verdict','A drive is a powerful long shot, usually from the tee; a putt is a gentle short stroke.','distinction')]);
P('puzzle','From Middle English pusle, possibly a frequentative of pose “perplex”; the noun is a problem/game, while the verb means confuse or think hard.',[C('puzzle.s1','通用','The children finished a 500-piece puzzle of the harbor.','孩子们拼完了一幅五百片的港口拼图。','solve/do/assemble a puzzle','名词，指需要组合或解答的游戏、难题。','pieces form a picture.','通用'),C('puzzle.s2','通用','Her sudden change of plans was a puzzle to her colleagues.','她突然改变计划让同事们感到困惑。','be a puzzle to someone','名词，指令人不解的事情或困惑感。','colleagues cannot understand the change.','通用'),C('puzzle.s3','通用','The missing page puzzled the archivist for hours.','缺失的那一页让档案员困惑了好几个小时。','puzzle someone; puzzle over + problem','及物动词，表示使人不解，也可指苦思某问题。','archivist is confused by missing page.','通用')],M('The missing number puzzled the student because it was obvious and immediately understood.','The missing number puzzled the student because no pattern explained it.','若答案显而易见且立即理解，就不会使人困惑。','meaning'),[Q(1,'A 500-piece picture puzzle is something you…','assemble to form a complete image','wear to protect your eyes','submit as a legal clause','Puzzle as a noun can be a game assembled from pieces.','meaning'),Q(2,'“The delay was a puzzle to the passengers” means…','they could not understand the delay','they assembled the delay into a picture','the delay was a toy','Sense 2 is a confusing or unexplained matter.','meaning'),Q(3,'If a clue puzzles a detective, it…','confuses or challenges the detective','solves the case automatically','proves the detective’s innocence','Puzzle as a verb means make someone unable to understand.','context'),Q(3,'Which construction is correct?','She puzzled over the map.','She puzzled the map over at.','She puzzled to the map over.','Puzzle over means think hard about a problem or question.','grammar')]);
P('puzzling','From puzzle + -ing; puzzle may derive from Middle English pusle. Puzzling describes something difficult to explain or understand.',C('puzzling.s1','通用','The puzzling gap in the records lasted exactly one week.','记录中令人费解的空缺恰好持续了一周。','puzzling pattern/result/question','形容词，指事实不符合明显解释、让人困惑。','gap raises an unexplained question.','通用'),M('The puzzling answer was perfectly clear to everyone and raised no questions.','The puzzling answer left everyone unsure what it meant.','人人都清楚理解且毫无疑问的答案并不 puzzling。','meaning'),[Q(1,'A puzzling result is one that is…','hard to understand or explain','already known by everyone','measured in quarts','Puzzling means causing confusion because an explanation is unclear.','meaning'),Q(1,'Which noun commonly follows puzzling?','question','proton','purse','Puzzling question is a natural collocation.','collocation'),Q(1,'Why might a scientist call a result puzzling?','It conflicts with the expected pattern.','It exactly confirms every prediction.','It is written in purple ink.','A puzzling result is difficult to reconcile with an obvious explanation.','context'),Q(1,'Choose the correct sentence.','The puzzling noise came from behind the wall.','The noise puzzling came from behind the wall.','The puzzlingly noise came from behind the wall.','Puzzling is an adjective modifying the noun noise.','grammar')]);
P('pylon','From French pylône, from Greek pylōn “gateway”; in English it can mean a tall electricity-support tower or a marker tower at an airfield/gateway.',C('pylon.s1','工程','A steel pylon carries high-voltage cables across the valley.','一座钢制高压线塔将高压电缆架过山谷。','electricity pylon; power-line pylon','指支撑输电线路的高塔，也可指标示通道的塔柱。','structure supports overhead cables.','工程'),M('The pylon carried underground pipes beneath the street, with no cables attached.','The pylon carried overhead electricity cables above the street.','输电塔支撑架空线路；没有电缆且地下管道不是典型 pylon。','meaning'),[Q(1,'An electricity pylon is built to…','support overhead power cables','store water underground','mark a quarter of a circle','Pylon commonly names a tall structure carrying power lines.','meaning'),Q(1,'Which phrase is natural?','a power-line pylon','a pylon of soup','pylon to be queasy','Power-line pylon is a common compound.','collocation'),Q(1,'A pilot sees two pylons marking an airfield entrance. Here they serve as…','marker towers','electrical batteries','parts of a pyramid','Pylon also refers to tower-like markers at an entrance or airfield.','context'),Q(1,'What might be attached to an electricity pylon?','high-voltage wires','a golf ball in a cup','a survey questionnaire','Pylons support overhead cables.','meaning')]);
P('pyramid','From Greek pyramis, probably influenced by Egyptian terms for the monumental structures; it names the ancient building, a geometric solid, or a tiered system.',[C('pyramid.s1','历史','The ancient pyramid contained burial chambers built for a pharaoh.','这座古代金字塔内有为法老建造的墓室。','an ancient/Egyptian pyramid','名词，指方形底座、三角形侧面的巨大建筑。','burial structure is historical monument.','历史'),C('pyramid.s2','数学','The solid has a square base and four triangular faces, so it is a pyramid.','这个立体有一个正方形底面和四个三角形侧面，因此是棱锥。','a square/triangular pyramid','数学中指底面为多边形、侧面汇于顶点的立体。','geometric definition.','数学'),C('pyramid.s3','社会','The organization has a pyramid structure, with many workers and few executives.','这个组织呈金字塔式结构，基层员工多而高管少。','a pyramid structure/scheme','引申指底部宽、顶部窄的层级体系；也可指金字塔骗局。','many at base, few at top.','社会')],M('A square-based pyramid has a flat circular base and no triangular sides.','A square-based pyramid has a square base and triangular sides that meet at a point.','圆底立体是圆锥，不是方底且侧面为三角形的棱锥。','distinction'),[Q(1,'An Egyptian pyramid is primarily…','a monumental building with sloping triangular sides','a four-sided flat drawing only','a unit of liquid volume','The historical sense is a large pyramid-shaped structure.','meaning'),Q(2,'A geometric pyramid has…','a polygon base and triangular faces meeting at a point','two circular bases and a curved side','four equal square faces with no apex','A pyramid’s triangular side faces converge at an apex above its base.','meaning'),Q(3,'A company with a pyramid structure has…','many people at lower levels and fewer at the top','one person at every level in a circle','no hierarchy at all','The figurative sense describes a wide base narrowing toward a top.','context'),Q(3,'Why is a pyramid scheme named that way?','its organization is wide at the bottom and narrows toward the top','it is built from ancient stone','it measures the height of a pyramid','The name reflects the tiered structure of participants.','meaning')]);
P('pyrotechnics','From Greek pyr “fire” + technē “art, skill,” through French pyrotechnie; it means the art of making fireworks or a fireworks display.',C('pyrotechnics.s1','娱乐','The festival ended with pyrotechnics over the river.','节庆活动以河上空的烟火表演收尾。','pyrotechnics display/show','名词，指烟火制造技术或烟火表演。','firework display closes the festival.','娱乐'),M('The pyrotechnics show used only silent paper lanterns and no fireworks or fire effects.','The lantern display used no pyrotechnics, while the later show used fireworks.','pyrotechnics 涉及烟火或火焰特效；纯纸灯笼不属于烟火。','meaning'),[Q(1,'A pyrotechnics display is a display of…','fireworks or controlled fire effects','quietly arranged paper books','mathematical pyramids','Pyrotechnics is the art or display of fireworks.','meaning'),Q(1,'Which phrase is natural?','a pyrotechnics show','a pyrotechnics of four liters','pyrotechnics yesterdayly','Pyrotechnics can be used as a plural-form noun modifying show/display.','collocation'),Q(1,'A festival hires a pyrotechnics team. What does the team specialize in?','fireworks and their safe production','surveying public opinion','building a queue','The word refers to fireworks technology or performance.','context'),Q(1,'Which word part in pyrotechnics relates to fire?','pyr-','-technics','-ics','Greek pyr means fire.','word-formation')]);
P('python','From Greek Pythōn, the name of a serpent in Greek myth; the modern animal name refers to a large nonvenomous constricting snake.',C('python.s1','生物','The python wrapped around a branch while waiting for prey.','这条蟒蛇盘绕在树枝上等待猎物。','a python constricts prey','名词，指蟒科的大型无毒蛇，靠缠绕挤压捕猎。','snake coils around its perch.','生物'),M('The python injected venom through hollow fangs and killed the mouse.','The python constricted the mouse in its coils.','蟒蛇主要以缠绕窒息猎物，不是靠毒牙注入毒液。','distinction'),[Q(1,'A python is a…','large nonvenomous snake that constricts prey','small venomous fish','bird that nests in trees','Pythons are snakes that kill prey by constriction.','meaning'),Q(1,'Which behavior is associated with a python?','coiling around prey','injecting venom like a cobra','building a paper nest','Pythons are constrictors, using their coils to squeeze prey.','context'),Q(1,'Which sentence is accurate?','The python is a snake.','The python is a four-sided polygon.','The python is a liquid measure.','Python names a snake, distinct from geometric and measurement terms.','meaning'),Q(1,'A python is called nonvenomous because it…','does not use venom to subdue prey','cannot bite at all','lives only in cold water','Pythons are nonvenomous constrictors, though they can bite.','distinction')]);
P('quadrangle','From Latin quadrangulum, from quadri- “four” + angulus “angle”; it is a four-sided shape or a courtyard enclosed by buildings.',[C('quadrangle.s1','数学','The students sketched a quadrangle with four straight sides.','学生画了一个有四条直边的四边形。','a quadrangle with + sides','几何上指四边形；也可指四方形院落。','four sides define the figure.','数学'),C('quadrangle.s1','地理','Students crossed the university quadrangle between classes.','学生们课间穿过大学的四方院。','college/university quadrangle','建筑语境中指被建筑物围起的四方庭院。','campus courtyard is surrounded by buildings.','地理')],M('The quadrangle had five straight sides and no fourth angle.','The pentagon had five straight sides.','四边形必须有四条边；五边形应称 pentagon。','meaning'),[Q(1,'A quadrangle is a figure with how many sides?','four','three','six','The prefix quadri- means four, and a quadrangle has four angles/sides.','word-formation'),Q(1,'A university quadrangle is often…','a courtyard surrounded by buildings','a high-voltage tower','a snake enclosure','Quadrangle can refer to a square or rectangular campus courtyard.','context'),Q(1,'Which shape can be a quadrangle?','a rectangle','a triangle','a circle','A rectangle has four straight sides and is a quadrangle.','meaning'),Q(1,'Which word part signals “four” in quadrangle?','quadri-','-angle','-gle','Quadr(i)- derives from Latin for four.','word-formation')]);
P('quadrant','From Latin quadrans “quarter,” from quattuor “four”; it names one of four parts of a plane/circle or a quarter-circle measuring device.',[C('quadrant.s1','数学','The point lies in the upper-right quadrant of the coordinate plane.','这个点位于坐标平面的右上象限。','first/second/third/fourth quadrant','由两条坐标轴分成的四个区域之一；也可指四分之一圆。','axes divide plane into four regions.','数学'),C('quadrant.s1','数学','The navigator used a quadrant to estimate the star’s altitude.','导航员用四分仪估算恒星的高度角。','measure with a quadrant','历史上用于测量天体高度角的仪器。','instrument measures angle.','天文')],M('The upper-right quadrant is one of five regions formed by two perpendicular axes.','The upper-right quadrant is one of four regions formed by two perpendicular axes.','两条垂直坐标轴把平面分成四个象限，不是五个。','measurement'),[Q(1,'Two axes divide a plane into four regions. Each region is a…','quadrant','quadruped','quarterly','A quadrant is one quarter of a circle or coordinate plane.','meaning'),Q(1,'Where is the second quadrant in a standard coordinate plane?','upper left','lower right','the center point only','The upper-left region is the second quadrant under the usual numbering.','context'),Q(1,'A historical quadrant helped a navigator measure…','the altitude angle of a celestial object','the weight of a ship','the color of a map','A quadrant was an instrument for measuring angles, including celestial altitude.','meaning'),Q(1,'Which word is closest to quadrant in its geometric sense?','quarter-section','whole circle','straight line','A quadrant is a quarter of a plane or circle.','meaning')]);
P('quadrilateral','From Latin quadrilaterus, from quadri- “four” + latus “side”; it describes a four-sided plane figure or something bounded by four straight sides.',C('quadrilateral.s1','数学','A trapezoid is a quadrilateral because it has four straight sides.','梯形是四边形，因为它有四条直边。','quadrilateral figure','名词或形容词，指有四条边的平面图形。','four sides make it a member of this class.','数学'),M('A quadrilateral has exactly three sides and three vertices.','A triangle has three sides and three vertices.','三条边的图形是三角形；quadrilateral 有四条边。','meaning'),[Q(1,'What defines a quadrilateral?','four straight sides','four curved surfaces','three equal angles only','A quadrilateral is a four-sided polygon.','meaning'),Q(1,'Which shape is a quadrilateral?','a square','a pentagon','a circle','A square has four straight sides, so it is a quadrilateral.','context'),Q(1,'Which prefix in quadrilateral signals four?','quadri-','tri-','penta-','Quadri- means four; tri- means three and penta- five.','word-formation'),Q(1,'A quadrilateral can have which number of vertices?','four','two','seven','A plane quadrilateral has four vertices, one at each corner.','meaning')]);
P('quadruped','From Latin quadrupes “four-footed,” from quadri- “four” + pes “foot”; a quadruped is an animal that walks on four feet.',C('quadruped.s1','生物','The horse is a quadruped, while the bird walks on two legs.','马是四足动物，而鸟用两条腿行走。','a quadruped such as + animal','名词，指以四足行走的动物。','horse has four walking limbs.','生物'),M('The dog is a quadruped because it walks on two legs.','The dog is a quadruped because it walks on four legs.','quadruped 意为四足行走；两条腿应称 biped。','meaning'),[Q(1,'A quadruped moves using how many feet?','four','two','eight','Quadru- means four, and a quadruped is a four-footed animal.','word-formation'),Q(1,'Which is a quadruped?','a horse','a human walking upright','a fish swimming with fins','A horse ordinarily walks on four legs.','context'),Q(1,'A two-footed animal is called a…','biped','quadruped','quadrangle','Biped means two-footed, contrasting with quadruped.','distinction'),Q(1,'Which phrase is natural?','a quadruped mammal','a quadruped of a circle','quadruped by one quarter','Quadruped classifies animals with four walking feet.','collocation')]);
P('quadruple','From Latin quadruplus “fourfold,” from quattuor “four”; it can mean make four times as much, become four times as much, or fourfold.',[C('quadruple.s1','通用','The new grant will quadruple the lab’s annual testing budget.','这笔新拨款将使实验室年度检测预算增加到原来的四倍。','quadruple something','及物动词：使数量或规模变为四倍。','grant multiplies budget by four.','通用'),C('quadruple.s2','通用','Online orders quadrupled during the holiday week.','假日期间，线上订单数量增至原来的四倍。','something quadruples','不及物动词：自身增长到四倍。','orders rise fourfold.','通用'),C('quadruple.s3','通用','The hotel charged a quadruple rate for the large family suite.','酒店对大型家庭套房收取四倍价格。','quadruple the amount/size/rate','形容词：四倍的、四重的。','rate is four times the reference amount.','通用')],M('The team quadrupled its staff from four people to eight.','The team doubled its staff from four people to eight.','从4增至8是翻倍；quadruple 表示变为4倍，即16人。','measurement'),[Q(1,'To quadruple a budget is to make it…','four times as large','twice as large','one quarter as large','Quadruple means multiply by four.','meaning'),Q(2,'If the number of orders quadruples, the number…','becomes four times its original size','falls to zero','stays exactly the same','The intransitive verb describes an amount growing fourfold.','meaning'),Q(3,'A quadruple room is a room intended for…','four people','one person only','a quarter of a person','The adjective quadruple means fourfold; in accommodation it can indicate four occupants.','context'),Q(1,'A price rises from $5 to $20. It has…','quadrupled','tripled','doubled','Twenty is four times five, so the price quadrupled.','measurement')]);
P('quail','From Old French quaille, of Germanic origin; the noun names a small short-tailed ground-dwelling game bird.',C('quail.s1','通用','A quail darted through the grass near the field path.','一只鹌鹑从田间小路旁的草丛中窜过。','a quail; a covey of quail','名词，指体型较小、尾短的地栖猎鸟。','bird runs through grass.','自然'),M('The quail soared on broad wings above the clouds for hours like an albatross.','The quail ran through the grass on its short legs.','鹌鹑是地栖小鸟，不会像信天翁那样长时间高空翱翔。','meaning'),[Q(1,'A quail is a type of…','small ground-dwelling bird','large whale','four-sided geometric figure','Quail names a small short-tailed game bird.','meaning'),Q(1,'Where might you most likely see a quail?','running through grass or brush','swimming in deep ocean water','perched on a high-voltage cable in flight','Quail commonly live and move near the ground.','context'),Q(1,'Which phrase is natural?','a covey of quail','a quail of three liters','quail to the courthouse','A covey is a group of game birds such as quail.','collocation'),Q(1,'Which animal is a quail?','a small partridge-like bird','a constricting snake','a species of mineral','Quail is a bird, not a snake or mineral.','meaning')]);
P('quaint','From Middle English queinte “skillful, ingenious,” from Old French cointe; its meaning shifted to attractively old-fashioned or oddly charming.',[C('quaint.s1','通用','The inn’s quaint rooms had crooked floors and hand-painted signs.','客栈古雅别致的房间里有倾斜的地板和手绘招牌。','quaint village/house/charm','形容有吸引力的老式风格，常带怀旧或别致意味。','old features are presented as charming.','通用'),C('quaint.s2','通用','His quaint explanation made the children laugh because it was so oddly phrased.','他奇特有趣的解释措辞古怪，逗得孩子们发笑。','a quaint expression/idea','也可指令人觉得奇特或滑稽的事物。','odd wording is amusing.','通用')],M('The quaint modern glass tower had no old-fashioned features and looked completely ordinary.','The modern glass tower looked sleek and contemporary rather than quaint.','完全普通且没有老式或奇特之处的高塔不应称 quaint。','meaning'),[Q(1,'A quaint village is usually…','attractively old-fashioned','newly built in a uniform modern style','dangerous because it is a snake','Quaint commonly describes something charmingly old-fashioned.','meaning'),Q(2,'A quaint explanation makes listeners smile because it is…','oddly phrased in an amusing way','mathematically exact with no unusual wording','a formal legal punishment','Sense 2 can mean unusual or amusingly strange.','meaning'),Q(1,'Which phrase is natural?','a quaint little shop','a quaint of three quarters','quaint to write a questionnaire','Quaint naturally modifies a place or object with charmingly unusual style.','collocation'),Q(1,'A tourist admires a cottage’s old sign and uneven stone path. The cottage seems…','quaint','quantifiable','quarrelsome','The old-fashioned, charming details support quaint.','context')]);
P('quake','From Old English cwacian “shake, tremble”; it can describe the ground shaking, a person trembling, or an earthquake.',[C('quake.s1','地质','The ground began to quake as the underground fault shifted.','地下断层移动时，地面开始震动。','the ground/building quakes','动词：地面或建筑物剧烈震动。','fault movement shakes the ground.','地质'),C('quake.s2','情感','The witness quaked with fear when the lights went out.','灯熄灭时，目击者吓得发抖。','quake with fear/cold','动词：因恐惧、寒冷或强烈情绪而颤抖。','fear causes trembling.','情感'),C('quake.s3','地质','The coastal quake damaged several old buildings.','这场沿海地震损坏了几栋老建筑。','a major/coastal quake','名词，是 earthquake 的简称。','noun names a seismic event.','地质')],M('The building quaked because the ground remained perfectly still and nothing shook.','The building quaked as the ground shook beneath it.','若没有任何震动，就不能说建筑物 quaked。','meaning'),[Q(1,'If the ground quakes, it…','shakes strongly','becomes perfectly motionless','turns into a liquid','Quake as a verb can describe the earth shaking.','meaning'),Q(2,'A person quaking with fear is…','trembling because they are frightened','quietly calculating a quantity','making a formal proposal','Sense 2 describes bodily trembling from fear or cold.','context'),Q(3,'“A quake damaged the harbor” means…','an earthquake caused damage','a question was asked at the harbor','a bird entered the harbor','Quake as a noun is a short form of earthquake.','meaning'),Q(2,'Which phrase is natural?','quake with fear','quake at a questionnaire of','quake for a quarter to','The common construction is quake with fear, cold, or another strong feeling.','collocation')]);
P('quaker','From Quake/quake + -er; Quaker became the name of the Religious Society of Friends. A traditional explanation links it to trembling during worship, though accounts vary.',C('quaker.s1','宗教','The Quaker meeting began in silence, with members waiting for anyone moved to speak.','贵格会聚会在静默中开始，成员们等待有人受到感召而发言。','a Quaker meeting/Friend','名词，指基督教贵格会（宗教公谊会）成员。','silent worship is a recognized practice.','宗教'),M('The Quaker service required a priest to perform elaborate rites in a decorated church.','The Quaker meeting was held in silence without a priest or elaborate rites.','贵格会聚会传统上强调静默礼拜、简朴形式，并不以神父和繁复仪式为典型。','meaning'),[Q(1,'A Quaker is a member of…','the Religious Society of Friends','a scientific society that studies quarks','a group of ancient Egyptian builders','Quaker is the common name for a member of the Friends movement.','meaning'),Q(1,'What may occur at a traditional Quaker meeting?','silent worship until a member feels moved to speak','a required elaborate mass led by a priest','a golf tournament','Some Quaker meetings use silent worship with participants speaking as moved.','context'),Q(1,'Which phrase is natural?','a Quaker community','a Quaker of 400 milliliters','quaker the river','Quaker can modify community, meeting, or beliefs.','collocation'),Q(1,'Which historical feature is associated with Quakers?','simple worship and a Protestant religious tradition','the invention of the pyramid','a four-day quarantine','Quakers are a Christian movement known for simple forms of worship.','meaning')]);
P('qualification','From qualify + -ation; qualify comes from Medieval Latin qualificare “describe by qualities.” Qualification means a credential or a skill required for a role.',C('qualification.s1','职业','The job requires a teaching qualification and two years of classroom experience.','这份工作要求具备教师资格，并有两年课堂经验。','a qualification in + field; hold a qualification','可指考试、课程取得的正式证书，也可指任职所需资质。','job states credential requirement.','职业'),M('Her engineering qualification was proof that she had never studied or passed any course.','Her engineering qualification showed that she had completed the required training.','qualification 是取得培训或考试后证明资质的凭证，不是从未学习的证明。','meaning'),[Q(1,'A teaching qualification is…','a credential showing the holder met a required standard','a question about teaching','a piece of classroom furniture','Qualification can mean an official credential.','meaning'),Q(1,'Which phrase is natural?','a qualification in nursing','a qualification to a sandwich','qualification into yesterday','A qualification in a subject names the field of training.','collocation'),Q(1,'A job lists a degree as a qualification. This means applicants need…','that credential or an equivalent skill','a purple uniform','a four-sided office','Qualification can be a credential or skill required for a role.','context'),Q(1,'Which word names a person’s quality or credential, not the act of making something eligible?','qualification','qualify','qualifyingly','Qualification is the noun for a credential or required skill.','word-formation')]);
P('qualified','From qualify + -ed; qualify derives from Medieval Latin qualificare. Qualified means having the skills, training, or credentials needed for a task.',C('qualified.s1','职业','Only qualified electricians may inspect the high-voltage wiring.','只有合格的电工才能检查高压线路。','qualified for/as + role','形容词，说明具备岗位所需能力或资质。','specialist work requires verified training.','职业'),M('The untrained applicant was qualified to repair the high-voltage system despite lacking any certification.','The trained applicant was qualified to repair the high-voltage system after completing certification.','完全没有培训或资质的人不能据此被称为 qualified electrician。','meaning'),[Q(1,'A qualified electrician is someone who…','has the required training or credentials','has never handled electrical equipment','is merely interested in electricity','Qualified means having the ability or formal requirements for a task.','meaning'),Q(1,'Which preposition fits? “She is qualified ___ the post.”','for','between','under of','Qualified for a job or role is the standard pattern.','grammar'),Q(1,'Why hire a qualified inspector?','the inspector has demonstrated the required competence','the inspector has a colorful uniform','the inspector can postpone all repairs','A qualification signals the necessary skill or credential.','context'),Q(1,'Which sentence is correct?','He is qualified to lead the safety review.','He is qualified leading to the safety review.','He qualified to leading the review yesterdayly.','Qualified can be followed by to + infinitive to describe ability.','grammar')]);
P('qualify','From Medieval Latin qualificare “describe by qualities,” from qualis “of what kind”; it means meet or confer requirements, limit a statement, or modify grammatically.',[C('qualify.s1','考试','The runner qualified for the final by finishing in the top three.','这名跑者以前三名的成绩取得了决赛资格。','qualify for + competition/role','达到标准而获得资格或晋级。','placing meets entry standard.','考试'),C('qualify.s2','通用','Her years of fieldwork qualify her to lead the survey.','她多年的实地工作使她有资格带领这项调查。','qualify someone to do something','使某人具备资格、训练或能力。','experience gives competence.','职业'),C('qualify.s3','书面','I support the proposal, but I must qualify that statement: it needs more testing.','我支持这项提案，但必须对这一说法作限定：它还需要更多测试。','qualify a claim/statement','给说法加限制或条件，避免过于绝对。','speaker narrows the claim.','书面'),C('qualify.s4','语言','In “remarkably clear,” the adverb remarkably qualifies the adjective clear.','在“格外清楚”中，副词 remarkably 修饰形容词 clear。','word qualifies/modifies another word','语法义：修饰另一词并补充其意义。','adverb modifies adjective.','语言')],M('A runner qualified for the final by finishing last in a field where only the top three advanced.','A runner failed to qualify for the final by finishing last when only the top three advanced.','只取前三名时，最后一名不能取得晋级资格。','meaning'),[Q(1,'A swimmer qualifies for the final by…','meeting the required standard','missing the qualifying time','buying a swimsuit','Qualify for means meet the conditions for entry or advancement.','meaning'),Q(2,'Experience may qualify someone to manage a project. It…','gives that person the necessary ability or credentials','removes the person’s skills','makes the project a question','Qualify someone to do something means make them fit or eligible.','meaning'),Q(3,'To qualify a claim is to…','add a limitation or condition to it','prove it is always true without exception','translate it into another language','Qualify can make a statement less absolute by adding a caveat.','context'),Q(4,'In “very bright,” the adverb very qualifies…','the adjective bright','the noun “very”','the verb “bright”','Qualify in grammar means modify or limit another word’s meaning.','grammar')]);
P('qualitative','From quality + -ative; quality comes from Latin qualitas “nature or character.” Qualitative concerns kind or characteristics rather than numerical amount.',C('qualitative.s1','科学','The researchers used qualitative interviews to understand patients’ experiences.','研究人员通过定性访谈了解患者的经历。','qualitative research/data/analysis','形容词，关注性质、感受或特征，而非数值数量。','interviews explore experiences in words.','科学'),M('The qualitative study reported only exact measurements in kilograms and no descriptions or themes.','The quantitative study reported exact measurements in kilograms.','以精确数值和测量为核心是 quantitative，不是 qualitative。','distinction'),[Q(1,'A qualitative interview study mainly analyzes…','descriptions, experiences, and themes','only numerical totals','the weight of laboratory equipment','Qualitative research focuses on characteristics and meanings rather than quantity.','meaning'),Q(1,'Which phrase is natural?','qualitative evidence','qualitative of three liters','qualitative yesterdayly','Evidence can be described as qualitative when it is nonnumeric or descriptive.','collocation'),Q(1,'Researchers code open-ended comments into themes. Their approach is…','qualitative','quantitative','quadrilateral','Themes from descriptive responses are qualitative findings.','context'),Q(1,'Which contrast is accurate?','qualitative concerns kind; quantitative concerns amount','qualitative and quantitative both mean four-sided','qualitative measures only time','The terms distinguish characteristics from numerical quantity.','distinction')]);
P('qualitatively','From qualitative + -ly; qualitative derives from quality/Latin qualitas. The adverb means with respect to nature or kind rather than amount.',C('qualitatively.s1','学术','The two fabrics are qualitatively different: one is breathable, the other waterproof.','这两种织物在性质上不同：一种透气，另一种防水。','differ/compare qualitatively','副词说明比较的是特征或性质，而不是数量大小。','comparison concerns material behavior.','学术'),M('The samples differed qualitatively only because one weighed two grams more.','The samples differed quantitatively because one weighed two grams more.','重量差异是数量上的区别，应称 quantitative，而非 qualitative。','distinction'),[Q(1,'If two products differ qualitatively, they differ in…','their nature or characteristics','their number only','the time they were manufactured','Qualitatively refers to kind or character.','meaning'),Q(1,'Which sentence uses qualitatively correctly?','The teams were qualitatively different in their training methods.','The teams qualitatively numbered 12 and 14.','The qualitatively of the teams was measured.','Qualitatively modifies an adjective or verb to describe a difference in kind.','grammar'),Q(1,'A comparison focuses on taste and texture, not grams. It is made…','qualitatively','quantitatively','quarterly','Taste and texture are qualities rather than numerical amounts.','context'),Q(1,'Which word contrasts with qualitatively when comparing amounts?','quantitatively','puritanically','quaintly','Quantitatively describes comparison by numerical amount.','distinction')]);
P('quality','From Latin qualitas “character, nature,” from qualis “of what kind”; it can mean standard, characteristic, or high-grade.',[C('quality.s1','通用','The quality of the repair was clear when the door closed smoothly.','门关合顺畅，足以说明维修质量不错。','quality of + product/work','名词，指相对于标准而言的好坏程度。','smooth operation demonstrates workmanship.','通用'),C('quality.s2','通用','Patience is a quality that helps a teacher manage a busy class.','耐心是一种有助于教师管理繁忙课堂的品质。','a quality of/in a person','指人或物具有的特征、性质，常指优点。','patience is a personal trait.','通用'),C('quality.s3','通用','They bought a quality winter coat that lasted for years.','他们买了一件优质冬衣，穿了好几年。','quality + noun','形容词用法，表示品质优良。','coat is high-standard.','通用')],M('The quality of the repair was excellent because the door no longer closed and the hinges fell off.','The quality of the repair was poor because the door no longer closed and the hinges fell off.','故障加重说明维修质量差，而非 excellent。','meaning'),[Q(1,'The quality of a repair refers to…','how good the work is','the number of workers','the day it was completed','Sense 1 is a standard or degree of goodness.','meaning'),Q(2,'Patience is a personal quality. Here quality means…','a characteristic or trait','a measurement in quarts','a building material','Sense 2 names a feature or attribute of a person.','meaning'),Q(3,'A quality coat is…','well made or of a high standard','a coat that has no qualities','a coat sold by the quart','Quality before a noun can mean high-grade.','grammar'),Q(1,'Which phrase is natural?','the quality of the service','the quality under a coordinate axis','a quality to be put out','Quality of service refers to how well the service is delivered.','collocation')]);
P('qualm','Origin uncertain; recorded in English by the sixteenth century for a sudden attack of sickness or unease. A qualm is a doubt or moral scruple.',C('qualm.s1','通用','She had a qualm about charging the client for work she had not done.','对于向客户收取未完成工作的费用，她心里有些不安。','have qualms about + action','名词，常指对某事是否正确的突然疑虑或良心不安。','unearned charge causes a moral scruple.','通用'),M('He had no qualms about the honest report, so he felt deeply guilty for telling the truth.','He had no qualms about the honest report and felt comfortable telling the truth.','no qualms 表示没有疑虑或顾虑；“深感内疚”与此相矛盾。','meaning'),[Q(1,'A moral qualm is…','an uneasy doubt about whether an action is right','a certificate for a job','a type of four-legged animal','A qualm is a scruple or uncomfortable doubt about conduct.','meaning'),Q(1,'Which phrase is idiomatic?','have qualms about lying','qualm of four liters','qualms into a pyramid','Have qualms about an action is the common construction.','collocation'),Q(1,'A person accepts a questionable payment without qualms. They…','feel no serious moral hesitation about it','are unable to decide whether to accept it','have already returned every cent','Without qualms means without misgivings or scruples.','context'),Q(1,'Which is closest to qualm?','misgiving','qualification','quarrel','A qualm is a sudden misgiving or scruple.','meaning')]);
P('quandary','Origin uncertain; the English noun is recorded in the sixteenth century for a difficult predicament. A quandary is a confusing situation with no easy choice.',[C('quandary.s1','通用','The team was in a quandary over whether to delay the launch or risk a faulty release.','团队陷入两难：是推迟发布，还是冒险推出有缺陷的版本？','be in a quandary about/over + choice','指没有容易答案、必须在困难选项间作决定的处境。','both options carry serious costs.','通用'),C('quandary.s2','通用','The sudden change left me in a quandary about which route to take.','突如其来的变化让我不知道该选哪条路线。','leave someone in a quandary','也可指因不知如何行动而感到困惑。','speaker cannot choose a route.','通用')],M('The quandary was simple because only one obvious option existed and nobody was uncertain.','The quandary was difficult because both options carried serious risks.','没有选择困难或疑惑就不是 quandary。','meaning'),[Q(1,'A person in a quandary is…','facing a difficult decision or confusing situation','celebrating an easy success','measuring a triangle','Quandary is a predicament with no easy choice.','meaning'),Q(2,'Which phrase is natural?','left in a quandary','left in a qualmly','left a quandary into','A person can be left in a quandary when unsure what to do.','collocation'),Q(1,'A manager must choose between two costly options. She is in a…','quandary','quarantine','quadrant','The competing difficult choices create a quandary.','context'),Q(1,'Which situation is least likely to be a quandary?','choosing between two risky plans','being unsure which route to take','choosing a clearly labeled open door','A quandary requires difficulty or uncertainty; an obvious easy choice lacks that feature.','distinction')]);
P('quantifiable','From quantify + -able; quantify derives from Latin quantus “how much.” Quantifiable means measurable or expressible as a number.',C('quantifiable.s1','学术','Energy use is quantifiable from the building’s monthly meter readings.','可以根据建筑每月的电表读数对能耗进行量化。','quantifiable amount/effect','形容可用计数或测量转化为数字的属性。','meter provides numerical measure.','学术'),M('The team called customer happiness quantifiable but refused to collect any measurements or indicators.','The team called customer happiness difficult to quantify without suitable indicators.','若完全没有可计数或测量的指标，就不能据此称它 quantifiable。','meaning'),[Q(1,'A quantifiable effect is one that can be…','measured or expressed numerically','described only as a color','put to death','Quantifiable means capable of measurement in numbers or amounts.','meaning'),Q(1,'Which item is most easily quantifiable?','the number of calls received per hour','the beauty of a melody with no defined scale','a vague feeling with no indicators','Call counts can be directly counted.','context'),Q(1,'Which phrase is natural?','a quantifiable risk','a quantifiable at a quay','quantifiable to quarrel','Quantifiable commonly modifies measurable things such as risk, impact, or result.','collocation'),Q(1,'The suffix -able in quantifiable means…','capable of being quantified','already quantified yesterday','opposed to numerical measurement','-able indicates possibility or capability.','word-formation')]);
P('quantify','From Latin quantificare “determine the amount of,” from quantus “how much”; quantify means express or estimate something in numbers.',[C('quantify.s1','学术','The survey quantified residents’ daily water use in liters.','这项调查以升为单位量化了居民的日用水量。','quantify something as/in + unit','用数字或测量值表示数量。','liters provide numerical measure.','学术'),C('quantify.s2','通用','Researchers are still trying to quantify the long-term effects of the spill.','研究人员仍在努力估定这次泄漏的长期影响。','quantify the effect/extent/cost','也可表示评估某影响或问题的规模、严重程度。','researchers estimate magnitude.','通用')],M('The analyst quantified the loss as “somewhat bad” and gave no number or estimate.','The analyst quantified the loss as $2.4 million.','量化要求用数字或明确的数量估计；模糊评价本身并未 quantify。','meaning'),[Q(1,'To quantify water use is to…','express it as a measured amount','describe its color only','keep it in quarantine','Quantify means measure or state an amount numerically.','meaning'),Q(2,'A researcher tries to quantify the effects of a policy. The researcher estimates…','how large or serious the effects are','the policy’s spelling','who proposed the policy','Sense 2 means assess the scale or extent.','context'),Q(1,'Which sentence uses quantify correctly?','The report quantified the savings at $800 per month.','The report quantified the savings very purple.','The report quantified into the savings a committee.','Quantify can take a measured amount as a complement.','grammar'),Q(1,'Which question asks for a quantification?','How many liters were saved?','Was the water beautiful?','Who was the queen?','The first requests a numerical quantity.','distinction')]);
P('quantitative','From quantity + -ative; quantity derives from Latin quantitas “amount.” Quantitative concerns numbers, measurements, or amounts.',C('quantitative.s1','科学','The quantitative analysis compared the number of errors before and after training.','这项定量分析比较了培训前后的错误数量。','quantitative data/analysis/research','形容词，依赖可计数数据或数量测量。','error counts are numerical data.','科学'),M('The quantitative report contained only interview stories and no numerical measures.','The qualitative report contained interview stories and no numerical measures.','只有访谈叙述而无数值分析属于 qualitative，而不是 quantitative。','distinction'),[Q(1,'A quantitative study relies mainly on…','numerical measurements or counts','stories without any quantities','a four-sided figure','Quantitative research deals with amounts and numbers.','meaning'),Q(1,'Which phrase is natural?','quantitative data','quantitative of a color','a quantitative queues','Data can be quantitative when represented numerically.','collocation'),Q(1,'A poll reports that 62% favor a proposal. This is…','quantitative evidence','qualitative evidence only','a legal provision','The percentage is a numerical measure, making it quantitative.','context'),Q(1,'Which term contrasts with quantitative when focusing on experiences and themes?','qualitative','quantifiable','quarterly','Qualitative evidence focuses on kind and meaning rather than measured amounts.','distinction')]);
P('quantity','From Old French quantité, from Latin quantitas “amount,” from quantus “how much”; it means an amount, a large supply, or a measurable variable.',[C('quantity.s1','通用','Measure the quantity of flour before adding the water.','加水前先量好面粉的用量。','quantity of + uncountable/plural noun','表示有多少或多少个。','flour is measured as an amount.','通用'),C('quantity.s2','商业','The factory ordered a large quantity of replacement filters.','工厂订购了大量替换滤芯。','a large/small quantity of + noun','可强调大量；语境中常与质量相对照。','bulk order is emphasized.','商业'),C('quantity.s3','科学','In the equation, pressure is a measurable quantity.','在这个方程中，压力是一个可测量的量。','a physical/measurable quantity','指可测量或研究的某种量。','pressure has numerical value.','科学')],M('The quantity of water was exactly two meters tall.','The depth of the water was exactly two meters.','quantity 指多少；描述液体从表面到底部的垂直距离应说 depth。','distinction'),[Q(1,'The quantity of flour in a recipe is…','how much flour is used','the color of the flour','the cook’s qualification','Quantity means amount or number.','meaning'),Q(2,'A factory buys a large quantity of filters. It buys…','many filters','one filter only','filters measured by their color','Large quantity refers to a substantial amount or number.','meaning'),Q(3,'Pressure is called a physical quantity because it…','can be measured and assigned a value','is always a person','has no relation to measurement','A scientific quantity is a measurable property.','context'),Q(1,'Which phrase is grammatical?','a quantity of water','a quantity water of','quantity of waters is always countable','Quantity of is followed by the thing whose amount is discussed.','grammar')]);
P('quantum','From Latin quantum “how much,” neuter of quantus; in physics it is a discrete unit/amount, and more generally a fixed share or quantity.',[C('quantum.s1','通用','The photon carries a quantum of electromagnetic energy.','光子携带一份电磁能量量子。','a quantum of energy','物理学中指能量等物理量的离散最小份额或单位。','photon carries discrete energy.','物理'),C('quantum.s2','通用','The grant provided a small quantum of funding for each library.','这笔拨款为每座图书馆提供了一定数额的资金。','a quantum of + resource','较正式用法，指一份固定或明确数量。','each institution gets a defined share.','通用')],M('A quantum of funding meant an unlimited amount with no fixed share.','A quantum of funding meant a defined amount or share.','quantum 的一般义指固定的一份或数量，不表示无限量。','meaning'),[Q(1,'In physics, a quantum of energy is…','a discrete unit or amount of energy','a color of light only','an unlimited continuous quantity by definition','Quantum in physics refers to a discrete amount or unit.','meaning'),Q(2,'A small quantum of funding for each school is…','a defined share of money','a school’s four-sided courtyard','a legal execution','The broader sense means a fixed amount or share.','meaning'),Q(1,'Which phrase is natural in physics?','a quantum of energy','a quantum of yesterday','quantum the photon loudly','Quantum of energy is a standard scientific phrase.','collocation'),Q(1,'What idea is central to quantum in physics?','discrete amounts','unmeasurable moral doubts','large supplies of food','Quantum theory treats certain properties as occurring in discrete units.','context')]);
P('quarantine','From Italian quarantina “forty days,” from quaranta “forty”; it names a period of isolation or the act of isolating to prevent disease spread.',[C('quarantine.s1','健康','The dog remained in quarantine until the veterinarian confirmed it was healthy.','这只狗一直接受检疫隔离，直到兽医确认它健康。','in quarantine; a quarantine period','名词：为防止传染病传播而隔离的一段时间。','animal is kept apart pending checks.','健康'),C('quarantine.s2','健康','Officials quarantined the imported animals after a disease alert.','疾病警报发出后，官员隔离了进口动物。','quarantine someone/something','动词：隔离人员或动物以防疫。','authorities isolate animals.','健康')],M('Officials quarantined the exposed animals by mixing them with the healthy herd immediately.','Officials quarantined the exposed animals by keeping them separate from the healthy herd.','检疫隔离需将可能感染者分开，立即混养会增加传播风险。','meaning'),[Q(1,'A traveler is in quarantine. What is happening?','the traveler is kept apart to reduce disease transmission','the traveler has won a qualification','the traveler is learning to putt','Quarantine is a period of isolation to prevent infection spreading.','meaning'),Q(2,'Officials quarantined the animals. They…','isolated them as a disease precaution','gave them a new name','released them into a shared enclosure','The verb means place in isolation for health control.','meaning'),Q(1,'Which phrase is natural?','a two-week quarantine','a quarantine of purple','quarantine into a quail','A quarantine can be described by its duration.','collocation'),Q(1,'Why might imported animals be quarantined?','to monitor them and prevent possible disease spread','to teach them geometry','to ensure they meet a sales quota','Isolation allows observation and lowers transmission risk.','context')]);
P('quark','Coined by physicist Murray Gell-Mann in 1964 for an elementary particle; he drew the sound of the name from James Joyce’s Finnegans Wake. A quark is a constituent of hadrons.',C('quark.s1','物理','A proton contains two up quarks and one down quark.','一个质子由两个上夸克和一个下夸克组成。','up/down quark; quark inside a proton','名词，指构成质子、中子等强子的基本粒子。','proton’s quark composition.','物理'),M('A quark is a large animal that walks on four legs.','A quadruped is an animal that walks on four legs.','quark 是基本粒子；四足动物是 quadruped。','confusable'),[Q(1,'A quark is a fundamental particle found in…','protons and other hadrons','a school courtyard','a golfer’s bag','Quarks are constituents of protons, neutrons, and related particles.','meaning'),Q(1,'A proton contains which quark combination?','two up quarks and one down quark','two down quarks and one up quark','four purple quarks','A proton’s valence quarks are two up and one down.','context'),Q(1,'Which pair names quark types?','up and down','north and west','large and small','Up and down are names of quark flavors.','collocation'),Q(1,'Why is quark not a synonym for quadruped?','A quark is a particle; a quadruped is a four-footed animal.','Both words name an animal.','A quadruped is a particle in an atom.','The terms belong to particle physics and zoology respectively.','distinction')]);
P('quarrel','From Old French querele, from Latin querela “complaint”; it can mean an angry argument, to argue, or a reason for complaint.',[C('quarrel.s1','通用','Their quarrel over the unpaid bill ended when the receipt was found.','找到收据后，他们因账单未付而起的争吵结束了。','a quarrel with/over + person/topic','名词，指愤怒的争执。','disagreement concerns bill.','通用'),C('quarrel.s2','通用','The neighbors quarrelled about where to place the shared fence.','邻居们为共用围栏应该放在哪里而争吵。','quarrel with someone about/over something','动词，指与人愤怒争论。','neighbors argue over placement.','通用'),C('quarrel.s3','书面','I have no quarrel with the budget itself, only with its timing.','我对预算本身没有异议，只是不赞成其时间安排。','have no quarrel with + idea/person','较正式地表示没有反对理由或异议。','speaker accepts budget but objects to timing.','书面')],M('They quarrelled peacefully by agreeing on every issue and expressing no disagreement.','They discussed the issue calmly and agreed without quarrelling.','完全同意且无争执不是 quarrel；这个词表示愤怒争论或异议。','meaning'),[Q(1,'A quarrel over a bill is…','an angry argument about who should pay','a written questionnaire','a scientific unit of energy','Quarrel as a noun means an angry disagreement.','meaning'),Q(2,'If neighbors quarrel about a fence, they…','argue over its placement','install it without discussion','put it back in a drawer','The verb means argue, often about a specific issue.','meaning'),Q(3,'“I have no quarrel with the plan” means…','I have no objection to it','I am eager to fight its author','I have never heard of a plan','The formal phrase means have no complaint or disagreement with something.','context'),Q(1,'Which preposition commonly follows quarrel for a topic?','over','through at','beside into','Quarrel over an issue or about a subject is standard.','grammar')]);
P('quarrelsome','From quarrel + -some; quarrel comes from Old French querele “complaint.” Quarrelsome describes someone inclined to argue or start disputes.',C('quarrelsome.s1','通用','The quarrelsome tenant argued with every neighbor about small repairs.','这位爱争吵的租户为小修小补和每个邻居争论。','a quarrelsome person/temper','形容容易争吵、常挑起纠纷。','repeated arguments over minor matters.','通用'),M('The quarrelsome mediator settled every disagreement quietly and never argued with anyone.','The patient mediator settled disagreements quietly and never argued with anyone.','平静调解且从不争吵不符合 quarrelsome。','meaning'),[Q(1,'A quarrelsome person tends to…','argue frequently','avoid every disagreement by listening','measure quantities','Quarrelsome means prone to quarreling.','meaning'),Q(1,'Which phrase is natural?','a quarrelsome neighbor','a quarrelsome of two quarts','quarrelsome the contract','The adjective naturally describes a person or temperament.','collocation'),Q(1,'Why might a group call a colleague quarrelsome?','the colleague starts disputes over minor matters','the colleague resolves disagreements calmly','the colleague is qualified for a job','Frequent argumentative behavior fits quarrelsome.','context'),Q(1,'Which word is closest to the opposite of quarrelsome?','peaceable','combative','argumentative','Peaceable contrasts with someone inclined to quarrel.','distinction')]);
P('quarry','From Anglo-French quarriere, from Medieval Latin quadraria “place where stone is squared”; the prey sense is a separate historical development. Quarry means a stone-extraction site or a hunted animal.',[C('quarry.s1','工业','The workers cut limestone from a quarry outside the village.','工人们在村外的采石场开采石灰岩。','a stone/lime quarry','名词：从地面开采石材的露天场地。','limestone is excavated there.','工业'),C('quarry.s2','自然','The falcon circled high above its quarry before diving.','猎鹰在俯冲前盘旋在猎物上空。','a predator’s quarry','名词：被捕食或追猎的动物。','falcon hunts the animal.','自然')],M('The falcon’s quarry was the stone pit where limestone was extracted.','The falcon’s quarry was the rabbit it was hunting.','猎鹰的 quarry 指猎物；采石场是 quarry 的另一个义项。','distinction'),[Q(1,'A stone quarry is a place where people…','extract stone from the ground','hold a debate','raise animals for milk','Quarry sense 1 is a site where stone is dug or cut out.','meaning'),Q(2,'A predator’s quarry is…','the animal it is hunting','the stone it uses to build a nest','the predator’s territory only','Quarry can mean the hunted prey.','meaning'),Q(1,'Which phrase refers to a mining site?','a marble quarry','the falcon’s quarry','quarry a suspect with questions','A marble quarry is a place where stone is extracted.','distinction'),Q(2,'The fox tracked its quarry through the snow. What did it track?','an animal it hoped to catch','a stone pit','a public questionnaire','The fox’s quarry is its prey.','context')]);
P('quart','From Old French quarte, from Latin quartus “fourth”; a quart is one quarter of a gallon and can also mean a container holding that amount.',[C('quart.s1','计量','Add one quart of water to the stockpot.','往汤锅里加入一夸脱水。','a quart of + liquid','液量单位；美制一夸脱为两品脱、四分之一美制加仑。','recipe measures volume.','计量'),C('quart.s2','生活','He bought a quart of milk in a reusable glass bottle.','他买了一夸脱牛奶，装在可重复使用的玻璃瓶里。','a quart bottle/container','也可指容量为一夸脱的容器。','container holds the measured amount.','生活')],M('The recipe calls for one quart of water, which is a unit of length equal to a foot.','The recipe calls for one quart of water, a unit of liquid volume.','quart 是液体容量单位，不是长度单位。','distinction'),[Q(1,'A quart measures…','liquid volume','temperature','electrical charge','A quart is a unit of liquid measure.','meaning'),Q(2,'“A quart of milk” may refer to…','the amount of milk or a container holding it','the milk’s color only','a quarter of a calendar year','Quart can name the quantity or a vessel holding that quantity.','meaning'),Q(1,'How many pints are in a US liquid quart?','two','four','eight','A US liquid quart equals two pints.','measurement'),Q(1,'Which phrase is natural?','a quart of soup','a quart of distance','quart the meeting off','Quart is a volume unit and combines naturally with a liquid.','collocation')]);
P('quarter','From Old French quartier, from Latin quartarius “one fourth”; it can name a fourth, fifteen minutes, a three-month period, a town district, a 25-cent coin, or dividing/providing lodging.',[C('quarter.s1','数学','One quarter of the class chose the morning session.','班上四分之一的人选择了上午场。','one quarter of + whole','名词：整体的四等份之一。','fraction equals one of four equal parts.','数学'),C('quarter.s2','时间','The train leaves at a quarter past six.','火车六点一刻发车。','a quarter past/to + hour','指十五分钟，即一小时的四分之一。','clock time is 15 minutes after six.','时间'),C('quarter.s3','商业','The company will publish its results for the third quarter.','公司将公布第三季度业绩。','first/second/third/fourth quarter','商业中指一年中的三个月期间。','report covers a three-month period.','商业'),C('quarter.s4','地理','They rented an apartment in the old quarter of the city.','他们在这座城市的老城区租了一套公寓。','the old/financial quarter','指具有特色的城镇地区或街区。','district is part of city.','地理'),C('quarter.s5','货币','The parking meter accepts a quarter.','这个停车计时器接受一枚25美分硬币。','a quarter coin','美国硬币，面值25美分。','coin is a US 25-cent piece.','货币'),C('quarter.s6','通用','The host quartered the visiting crew in a nearby school.','主人把来访队伍安置在附近的一所学校住宿。','quarter someone in/at + place','动词：把某人分成四份或安排其住宿。','crew is provided lodging.','通用')],M('The company’s fourth quarter lasted twelve months, not three.','The company’s fourth quarter lasted three months.','一个季度是一年四分之一，通常为三个月而非十二个月。','measurement'),[Q(1,'One quarter of 80 pages is…','20 pages','40 pages','60 pages','A quarter is one of four equal parts; 80 divided by 4 is 20.','measurement'),Q(2,'“A quarter past six” is what time?','6:15','6:45','6:30','A quarter of an hour is 15 minutes.','meaning'),Q(3,'A company’s third quarter usually covers…','three months','three years','one week','A business quarter is a three-month period.','meaning'),Q(5,'A US quarter is worth…','25 cents','10 cents','50 cents','A quarter is the 25-cent coin.','meaning')]);
P('quarterly','From quarter + -ly; quarter derives from Latin quartarius “one fourth.” Quarterly means occurring every three months or a magazine issued four times a year.',[C('quarterly.s1','通用','The board receives a quarterly financial report every three months.','董事会每三个月收到一份季度财务报告。','quarterly report/meeting','形容词：每季度发生或发布一次。','report recurs every three months.','通用'),C('quarterly.s2','通用','The magazine is published quarterly, in March, June, September, and December.','这本杂志按季出版，分别在三月、六月、九月和十二月发行。','published/paid quarterly','副词：每三个月一次。','four scheduled publication dates.','通用'),C('quarterly.s3','通用','She reads a literary quarterly devoted to new poetry.','她阅读一本专门刊登新诗的文学季刊。','a literary/scientific quarterly','名词：每年出版四期的杂志。','periodical comes out four times annually.','通用')],M('The quarterly report is issued every day, so it appears 365 times a year.','The daily report is issued every day; the quarterly report appears every three months.','quarterly 指每三个月一次，不是每天一次。','distinction'),[Q(1,'A quarterly meeting occurs…','once every three months','once every three days','once every four years','Quarterly describes a three-month interval.','meaning'),Q(2,'If a bill is paid quarterly, it is paid…','four times a year','every week','once every decade','Quarterly as an adverb means once every quarter, or four times yearly.','meaning'),Q(3,'A literary quarterly is…','a magazine published four times a year','a daily newspaper','a quarter of a novel','A quarterly can be a periodical issued every three months.','meaning'),Q(1,'Which phrase is natural?','quarterly earnings','quarterly yesterday','quarterly to a pyramid','Quarterly commonly modifies reports, earnings, reviews, or meetings.','collocation')]);
P('quartet','From Italian quartetto, from quarto “fourth,” ultimately Latin quartus; a quartet is a group of four, especially musicians performing together.',C('quartet.s1','音乐','The string quartet rehearsed Haydn’s piece before the concert.','弦乐四重奏在音乐会前排练海顿的作品。','string quartet; a quartet of + performers','名词：四位演奏者组成的乐团，也可指任何四人或四物组合。','four musicians rehearse together.','音乐'),M('The quartet had three musicians and was called a four-person ensemble.','The trio had three musicians; the quartet added a fourth.','quartet 必须由四个成员组成，三人组合是 trio。','meaning'),[Q(1,'How many performers are in a quartet?','four','three','five','The word quartet is formed from a root meaning four.','word-formation'),Q(1,'A string quartet usually includes…','four musicians playing string instruments','four singers with no instruments only','one musician and three audiences','A string quartet is a standard ensemble of four string players.','context'),Q(1,'Which phrase is natural?','a quartet of singers','a quartet of seven liters','quartet the light out','Quartet can be followed by a group of four performers.','grammar'),Q(1,'Which group has the same number of members as a quartet?','four violinists','three dancers','five runners','A quartet has four members.','meaning')]);
P('quartz','From German Quarz; the deeper origin of the German word is uncertain. Quartz is a hard crystalline mineral widely found in the earth’s crust.',[C('quartz.s1','通用','Clear quartz formed in a cavity inside the granite.','透明石英在花岗岩内部的空隙中形成。','a crystal/grain of quartz','名词，指坚硬、常呈玻璃光泽的矿物。','mineral crystal occurs in rock.','地质'),C('quartz.s2','通用','The wall clock uses a quartz crystal to keep time.','这只挂钟用石英晶体计时。','a quartz clock/watch','口语中可用 quartz 指由石英晶体控制的钟表。','crystal regulates the clock.','科技')],M('The quartz crystal was a soft liquid that dissolved as soon as it was touched.','The quartz crystal was a hard mineral that could scratch glass.','石英是坚硬矿物，不是轻触即溶的液体。','meaning'),[Q(1,'Quartz is best described as…','a hard mineral','a soft liquid','a type of four-person music group','Quartz is a hard crystalline mineral.','meaning'),Q(2,'A quartz clock uses a crystal to…','regulate timekeeping','store drinking water','measure the height of a star directly','Quartz crystals are used in timekeeping mechanisms.','context'),Q(1,'Which phrase is natural?','a quartz crystal','a quartz of soup','quartz the quarrel away','Quartz commonly modifies crystal, rock, clock, or watch.','collocation'),Q(1,'Why is quartz useful in watches?','its crystal can provide a stable oscillation for timekeeping','it is a type of battery made from milk','it is always purple','Quartz crystal oscillations can be used to keep time accurately.','meaning')]);
P('quasar','Shortened from “quasi-stellar radio source,” coined in 1964 by astrophysicist Hong-Yee Chiu; a quasar is an extremely luminous distant active galactic nucleus.',[C('quasar.s1','通用','The telescope detected a quasar billions of light-years away.','望远镜探测到数十亿光年外的一个类星体。','a distant/bright quasar','天文学名词：极遥远、极明亮的类星体。','object is distant and detected by telescope.','天文'),C('quasar.s2','通用','Astronomers used the quasar as a background beacon to study gas in the early universe.','天文学家把类星体当作背景信标，研究早期宇宙中的气体。','use a quasar to study + object','可作为探测早期宇宙或星际物质的研究对象。','bright background source illuminates intervening gas.','天文')],M('The quasar was a nearby dim asteroid reflecting sunlight weakly.','The quasar was a distant, intensely luminous galactic source.','类星体极遥远且异常明亮，并非附近暗淡的小行星。','distinction'),[Q(1,'A quasar is an object studied in…','astronomy','culinary arts','court procedure','Quasars are distant luminous sources in space.','meaning'),Q(2,'Why can a quasar help study gas between galaxies?','its bright light passes through intervening material','it is a gas sample brought to Earth','it blocks all background light','A bright quasar can act as a background source for absorption studies.','context'),Q(1,'Which description fits a quasar?','distant and extremely luminous','nearby and completely dark','a four-sided solid','Quasars are known for their great distance and luminosity.','meaning'),Q(1,'The word quasar was shortened from which expression?','quasi-stellar radio source','quarterly astronomical report','quartz star','Quasar combines elements of “quasi-stellar radio source.”','word-formation')]);
P('quash','From Old French quasser “break, annul,” from Latin quassare “shake violently”; it means formally set aside a decision or forcibly suppress unrest.',[C('quash.s1','法律','The appeals court quashed the conviction because key evidence was inadmissible.','上诉法院因关键证据不予采纳而撤销了定罪。','quash a conviction/order/claim','法律义：撤销、废止法院决定或诉求。','court annuls a conviction.','法律'),C('quash.s2','政治','Police moved to quash the violent disturbance before it spread.','警方在暴力骚乱蔓延前采取行动平息事态。','quash a rebellion/disturbance','以武力或权威制止骚乱、叛乱等。','authorities suppress unrest.','政治')],M('The appellate court quashed the conviction by confirming it and ordering the sentence carried out.','The appellate court upheld the conviction by confirming it and ordering the sentence carried out.','确认定罪并执行判决是 uphold，不是 quash（撤销）。','confusable'),[Q(1,'If an appeal court quashes a conviction, it…','sets aside or annuls it','confirms it and increases the sentence','turns it into a questionnaire','Quash in law means overturn or annul a decision.','meaning'),Q(2,'Authorities may quash a rebellion by…','suppressing it','publishing a quarterly report','building a quay','The second sense means forcibly put an end to unrest.','meaning'),Q(1,'Which collocation is natural?','quash an appeal','quash a glass of water','quash someone to a job','Courts can quash a conviction, order, or claim.','collocation'),Q(1,'Which verb contrasts with quash a ruling?','uphold','annul','overturn','Uphold means confirm, whereas quash means set aside.','distinction')]);
P('quay','From Anglo-French/Old French quai, probably from a Celtic source; a quay is a structure or landing place beside water where ships berth.',C('quay.s1','交通','The fishing boats were tied to the quay before dawn.','天亮前，渔船都系在码头边。','a quay beside/by the harbor','名词：水边供船只停靠、装卸的码头或岸边设施。','boats moored alongside.','交通'),M('The ship tied up at the quay in the middle of the desert, hundreds of miles from any water.','The ship tied up at the quay beside the harbor.','quay 必须位于水边，沙漠内远离水域的地点不合语义。','meaning'),[Q(1,'Ships are tied to a quay so they can…','berth beside the water','travel through a desert','measure a quarter of an hour','A quay is a waterside landing place for ships.','meaning'),Q(1,'Which phrase is natural?','along the quay','inside the quay of a calendar','quay up the question','Boats can be moored along or at a quay.','collocation'),Q(1,'A delivery arrives by boat at the quay. Where should the crew unload?','at the waterside landing structure','at a mountain summit','inside a courtroom','A quay provides access between vessels and the shore.','context'),Q(1,'What is a quay most closely related to?','a harbor landing place','a science questionnaire','a color shade','A quay is part of a harbor or waterfront.','meaning')]);
P('queasy','Origin uncertain; recorded in English in the sixteenth century for sickness or nausea. Queasy means feeling sick in the stomach, sometimes uneasy.',C('queasy.s1','健康','The winding bus ride made several passengers feel queasy.','蜿蜒的公交线路让几名乘客感到反胃。','feel/become queasy','形容胃部不适、恶心。','motion triggers nausea.','健康'),M('The queasy passenger felt perfectly well and ate a large meal without discomfort.','The nauseated passenger felt queasy and could not eat comfortably.','感觉完全良好且毫无不适与 queasy（反胃）相矛盾。','meaning'),[Q(1,'A queasy person may feel…','nauseated','hungry for a large meal only','ready to fall asleep because of boredom','Queasy means feeling sick in the stomach.','meaning'),Q(1,'Which situation may make someone queasy?','a rough boat trip','a calm walk on level ground','reading a clear questionnaire','Motion can cause nausea or queasiness.','context'),Q(1,'Which phrase is natural?','feel queasy','queasy a quart','feel queasinessly','Queasy commonly follows feel or become.','grammar'),Q(1,'Which is closest in meaning to queasy?','nauseated','qualified','quarrelsome','Nauseated describes the same stomach-sick feeling.','meaning')]);
P('queen','From Old English cwēn “woman, wife, queen,” from Germanic roots; it can be a female sovereign, a king’s wife, a leading woman, or a chess/card piece.',[C('queen.s1','政治','Queen Elizabeth addressed the parliament from the throne.','伊丽莎白女王在王座上向议会发表讲话。','queen regnant/queen of + country','女性君主，以王室身份统治国家。','woman rules in her own right.','政治'),C('queen.s2','历史','The queen attended the ceremony beside her husband, the king.','王后陪同丈夫国王出席了典礼。','the queen consort; wife of a king','指国王的妻子。','she is spouse of the reigning king.','历史'),C('queen.s3','文化','She was known as the queen of jazz for her powerful voice.','她以浑厚嗓音被誉为爵士乐女王。','queen of + field/activity','比喻某领域最出众或最有影响力的女性。','figurative title praises her prominence.','文化'),C('queen.s4','游戏','The queen moved diagonally across the chessboard to capture the bishop.','国际象棋皇后沿斜线移动，吃掉了象。','chess queen','棋子，通常可沿横、竖、斜线移动任意格数。','piece moves on board.','游戏'),C('queen.s5','游戏','I drew the queen of hearts from the deck.','我从牌堆里抽到了红桃皇后。','queen of + suit','纸牌中带女性人像、位于国王之下的牌。','card belongs to hearts suit.','游戏')],M('The chess queen can move only one square forward, just like a pawn.','The chess queen can move any number of squares in a straight line.','只能向前走一格的是兵；皇后可沿直线方向走任意格数。','distinction'),[Q(1,'A queen regnant is…','a woman who rules in her own right','the wife of a king only','a card in every chess game','Sense 1 is a female sovereign, distinct from a queen consort.','meaning'),Q(2,'The queen stood beside her husband, the king. Here queen means…','the king’s wife','the female ruler of a separate country','the most powerful chess piece','Sense 2 refers to a king’s wife.','context'),Q(3,'A “queen of jazz” is…','a highly prominent woman in jazz','a monarch who rules a country named Jazz','a playing card','The figurative use praises a leading woman in a field.','meaning'),Q(4,'How can a chess queen move?','any number of squares in a straight line','only one square forward','only in an L-shape','A queen combines rook-like and bishop-like movement.','context')]);
P('queer','From Scots/early modern English queer “strange, peculiar,” of uncertain deeper origin; the source senses here mean unusual, faintly ill, or suspicious. The word also has later identity-related uses not represented by these source senses.',[C('queer.s1','通用','A queer-shaped shadow appeared on the wall when the lamp moved.','灯移动时，墙上出现了一个形状古怪的影子。','queer-looking/queer-shaped','形容奇怪、不寻常；此义在一些语境中显得过时。','unusual shape is observed.','通用'),C('queer.s2','通用','I felt queer after the long ride and sat down for water.','长途乘车后我有点不舒服，便坐下来喝水。','feel queer','较旧用法：感到轻微恶心、眩晕或不适。','person feels physically unwell.','健康'),C('queer.s3','通用','There was something queer about the invoice: its account number had changed.','这张发票有些可疑：账户号码变了。','something queer about + situation','表示可疑、靠不住或不太对劲。','unexpected account change prompts suspicion.','通用')],M('The invoice seemed queer because it was completely ordinary, verified, and raised no suspicion.','The invoice seemed queer because its account number had changed without explanation.','若一切正常、经过核验且毫无可疑处，就不符合 queer 的“可疑”义。','meaning'),[Q(1,'In “a queer-shaped shadow,” queer means…','strange or unusual','a royal title','a unit of liquid measure','The first source sense is unusual or peculiar.','meaning'),Q(2,'If someone says “I feel queer,” in the older sense, they may mean…','slightly sick or faint','very confident about a job','ready to perform a golf putt','The second source sense is feeling physically uneasy or ill.','meaning'),Q(3,'“There is something queer about the invoice” suggests…','something seems suspicious or wrong','the invoice is a four-sided figure','the invoice has been paid in cash','The third source sense means suspicious or not trustworthy.','context'),Q(1,'Which phrase uses queer in the source’s “strange” sense?','a queer noise from the attic','a queen on the chessboard','a queasy stomach after sailing','A queer noise is unusual; queasy describes nausea.','distinction')]);
P('quell','From Old English cwellan “kill, destroy, quell”; the verb means put an end to a disturbance, fear, or other forceful problem.',C('quell.s1','政治','Negotiators worked through the night to quell the unrest in the capital.','谈判人员彻夜努力，试图平息首都的动乱。','quell unrest/fears/a disturbance','及物动词，指制止、压下或平息骚乱、恐惧等。','diplomacy aims to stop unrest.','政治'),M('The announcement quelled public fears by making everyone more frightened and increasing panic.','The announcement intensified public fears by increasing panic.','引发更多恐慌是加剧恐惧，不是 quell（平息）恐惧。','meaning'),[Q(1,'To quell a disturbance is to…','stop or suppress it','make it spread faster','measure it in quarts','Quell means put an end to a disturbance or rebellion.','meaning'),Q(1,'Which object commonly follows quell?','fears','a quartz crystal','a quartet','One can quell fears, unrest, or a disturbance.','collocation'),Q(1,'A clear explanation quelled the rumor. What happened?','the rumor was suppressed or brought to an end','the rumor became a stone quarry','the explanation delayed the rumor','Quell can mean suppress or stop something from continuing.','context'),Q(1,'Which is closest to quell?','suppress','provoke','pursue','Suppress and quell both mean bring something under control or stop it.','meaning')]);
P('quench','From Old English cwencan “extinguish”; it can satisfy thirst/desire, extinguish fire or feelings, or cool hot metal rapidly.',[C('quench.s1','通用','A glass of water quenched her thirst after the race.','比赛后，一杯水解了她的渴。','quench thirst/desire/curiosity','满足口渴，也可满足愿望或好奇心。','water satisfies thirst.','通用'),C('quench.s2','通用','The crew used sand to quench the small fire.','工作人员用沙子扑灭了小火。','quench/extinguish a fire; quench a feeling','熄灭火焰；也可平息强烈情绪。','sand stops combustion.','通用'),C('quench.s3','通用','The blacksmith quenched the heated blade in oil to harden it.','铁匠把烧热的刀刃放进油中淬火，使其变硬。','quench hot metal in water/oil','金属加工中快速冷却高温金属以改变硬度。','heated steel is rapidly cooled.','通用')],M('She quenched her thirst by avoiding all water after running in the sun.','She quenched her thirst by drinking cool water after running in the sun.','不喝水不会解渴；饮水才满足口渴。','meaning'),[Q(1,'Cold water can quench thirst by…','satisfying the need to drink','igniting a fire','hardening a steel blade','Sense 1 means satisfy thirst or a desire.','meaning'),Q(2,'A firefighter quenches a flame. The firefighter…','puts the fire out','delays the fire','makes the fire brighter','Quench can mean extinguish a fire.','meaning'),Q(3,'A blacksmith quenches hot steel by…','cooling it rapidly in a liquid','leaving it in a hot furnace indefinitely','painting it purple','Quenching metal is rapid cooling in water or oil.','context'),Q(1,'Which phrase can be used figuratively?','quench curiosity','quench a quadrant','quench a questionnaire into','Quench curiosity means satisfy a desire to know.','collocation')]);
P('query','From Latin quaerere “ask, seek,” via Anglo-French querre; as a noun it is a question or information request, as a verb to ask or express doubt.',[C('query.s1','书面','The editor sent a query asking whether the author could verify the date.','编辑发来一项询问，请作者核实日期。','send/answer a query','名词：为获得信息或核实事实而提出的问题。','request asks for verification.','书面'),C('query.s2','通用','The journalist queried the minister about the missing funds.','记者就失踪资金一事询问部长。','query someone about + topic','动词：提问、询问需要核实的信息。','journalist asks about a specific topic.','通用'),C('query.s3','书面','The auditor queried the unusually large travel expense.','审计员对异常高额的差旅费提出了质疑。','query a figure/decision','动词：对数字、决定或说法是否合理表示怀疑。','expense is questioned.','书面')],M('The auditor queried the expense by accepting it without checking or expressing any doubt.','The auditor approved the expense after checking it and finding no problem.','query 表示询问或质疑；毫无疑问地接受不符合其动词义。','meaning'),[Q(1,'A query sent to an editor is…','a question asking for information or confirmation','a final answer with no question','a kind of animal','Query as a noun means an inquiry or information request.','meaning'),Q(2,'A reporter queries a minister about a policy. The reporter…','asks the minister a question','silently approves the policy','puts the minister to death','Query as a verb means ask about something.','meaning'),Q(3,'An auditor queries an expense. The auditor…','expresses doubt about whether it is proper','pays it without review','turns it into a quarterly report','Query can mean question or challenge the reasonableness of a claim.','context'),Q(1,'Which phrase is natural?','answer a query','query a quart into a harbor','a query of four legs','A query can be sent, raised, or answered.','collocation')]);
P('quest','From Old French queste, from Latin quaerere “seek”; a quest is a long serious search or undertaking, and quest can also mean search over time.',[C('quest.s1','书面','The novel follows a knight on a quest to find a cure for the sleeping village.','小说讲述一位骑士踏上寻找解药、拯救沉睡村庄的征程。','a quest for + goal; go on a quest','名词：为寻找或实现重要目标而进行的长期探索。','journey is sustained and purposeful.','文学'),C('quest.s2','书面','The botanists quested for rare orchids in the remote valley.','植物学家在偏远山谷中四处寻找稀有兰花。','quest for + object','动词，指长时间、认真地寻求某物。','search is prolonged.','书面')],M('Their quest for the lost archive ended before they searched anywhere or made any effort.','Their search for the lost archive continued across several towns.','没有任何搜索行动就不能说开展了 quest。','meaning'),[Q(1,'A quest for a cure is…','a serious, sustained search for one','a quarterly financial statement','a short casual greeting','Quest means a long and important search or undertaking.','meaning'),Q(2,'To quest for a rare plant is to…','search for it over time','quench it with water','put it back in a drawer','The verb means search for something important or difficult to find.','meaning'),Q(1,'Which phrase is natural?','go on a quest for answers','go a quest at the answers','quest the answers by of','Go on a quest for something is a standard construction.','grammar'),Q(1,'A hero’s quest may involve…','a difficult journey toward an important goal','a routine queue at a ticket desk','a single measurement of a quart','A quest is often a long effort to achieve or find something significant.','context')]);
P('question','From Old French question, from Latin quaestio “inquiry,” from quaerere “ask”; it can be an inquiry, an issue/doubt, or the act of asking or challenging.',[C('question.s1','通用','The teacher asked a question about the final chapter.','老师提出了一个关于最后一章的问题。','ask/answer a question','名词：为获得信息而提出的问题。','teacher requests information.','通用'),C('question.s2','通用','The question of who will pay remains unresolved.','由谁付款这一议题仍未解决。','the question of + issue','名词：需要讨论或决定的事项。','matter awaits decision.','通用'),C('question.s3','通用','There is no question that the bridge needs urgent repairs.','这座桥需要紧急维修，这是毫无疑问的。','there is a question/doubt about','名词：不确定或对真实性的疑问。','idiom expresses certainty by denying doubt.','通用'),C('question.s4','法律','Police questioned the witness for two hours.','警方询问了这名证人两个小时。','question a witness/suspect','动词：系统地询问某人，常用于调查。','officials conduct an interview.','法律'),C('question.s5','通用','Residents questioned whether the new fee was fair.','居民质疑这项新费用是否公平。','question a claim/decision/whether-clause','动词：对其真实性、合理性或明智程度表示怀疑。','residents challenge fairness.','通用')],M('Police questioned the witness by refusing to ask anything or speak to her.','Police interviewed the witness and asked her questions.','question 作动词意为询问；完全不提问不能称为 questioned。','meaning'),[Q(1,'A teacher asks a question to…','get information or an answer','measure the classroom wall','make a decision without discussion','Question as a noun can be an inquiry seeking information.','meaning'),Q(2,'“The question of funding remains open” means…','the funding issue still needs a decision','someone asked a sentence aloud','funding is definitely settled','Question can mean an issue that needs discussion or resolution.','meaning'),Q(3,'“There is no question that she is qualified” means…','there is no doubt about it','she has not been asked anything','her qualification is being rejected','No question that expresses certainty rather than uncertainty.','context'),Q(4,'Police questioned a witness. They…','asked the witness questions, often formally','put the witness in a queue','gave the witness a job qualification','Question as a verb means interrogate or ask someone systematically.','meaning')]);
P('questionable','From question + -able; question derives from Latin quaestio “inquiry.” Questionable means doubtful, suspicious, or possibly wrong.',C('questionable.s1','通用','The accountant flagged a questionable charge that appeared twice on the invoice.','会计标记了一笔可疑费用，它在发票上重复出现。','questionable claim/decision/expense','形容可能错误、不诚实或值得怀疑的事物。','duplicate charge seems suspicious.','通用'),M('The questionable receipt was independently verified as genuine and accurate, with no concern at all.','The receipt was verified as genuine and accurate, so it was not questionable.','完全核验无误且毫无疑虑的收据不应称 questionable。','meaning'),[Q(1,'A questionable charge on an invoice is…','doubtful or possibly incorrect','a guaranteed correct measurement','a four-sided courtyard','Questionable means doubtful or likely to be wrong.','meaning'),Q(1,'Which noun commonly follows questionable?','decision','quark','queen','A decision can be described as questionable if its reasoning is doubtful.','collocation'),Q(1,'A questionable claim should be…','checked before being accepted','treated as certainly true without evidence','put out like a candle','The adjective signals a need for doubt or verification.','context'),Q(1,'Which is closest in meaning to questionable?','dubious','certain','verified','Dubious and questionable both express doubt.','meaning')]);
P('questionnaire','From French questionnaire, based on question; a questionnaire is a written set of questions used to collect information.',C('questionnaire.s1','通用','Participants completed a questionnaire about their commuting habits.','参与者填写了一份关于通勤习惯的问卷。','complete/fill in a questionnaire','名词：以书面问题收集资料的表格或文件。','respondents answer written items.','通用'),M('The researcher called a blank page with no questions a completed questionnaire.','The researcher called the completed form a questionnaire because it contained written questions.','不含任何问题的空白页不能作为已完成的问卷。','meaning'),[Q(1,'A questionnaire is used to…','collect information through a written set of questions','measure a quarter of a circle','put out a fire','Questionnaires gather responses to organized questions.','meaning'),Q(1,'Which verb commonly combines with questionnaire?','complete','quench','quarrel','People complete, fill in, or answer a questionnaire.','collocation'),Q(1,'A health researcher distributes a questionnaire. What do participants do?','answer its questions','inspect its quartz content','install it in a wall','A questionnaire is a data-collection form for respondents to answer.','context'),Q(1,'Which phrase is natural?','a questionnaire about sleep habits','a questionnaire into a pyramid','questionnaire to putt a ball','About introduces the topic covered by the questions.','grammar')]);
P('queue','From French queue “tail,” from Latin cauda “tail”; it means a line of people or an ordered set of tasks waiting, or to wait in line.',[C('queue.s1','生活','A queue formed outside the bakery before it opened.','面包店开门前，门外排起了队。','stand/wait in a queue','名词：等待轮到自己的人员队列。','customers line up for service.','生活'),C('queue.s2','生活','Passengers queued for tickets at the station.','乘客在车站排队买票。','queue for + service/item','动词：排队等候。','passengers wait in line.','生活'),C('queue.s3','技术','The print jobs remained in a queue until the shared printer was free.','打印任务一直留在队列中，直到共享打印机空闲。','a queue of tasks/jobs','名词：按顺序等待处理的任务或数据列表。','jobs wait for processing.','技术')],M('Passengers queued by scattering randomly across the station and never waiting their turn.','Passengers queued in a line and waited their turn.','queue 意为按序排队；随机散开且不等候轮次不是 queue。','meaning'),[Q(1,'People waiting their turn outside a shop form a…','queue','quasar','quadrant','Queue as a noun is a line of people waiting.','meaning'),Q(2,'Passengers queued for tickets. They…','waited in line to buy them','put the tickets to death','made the train run quarterly','Queue as a verb means wait in a line.','meaning'),Q(3,'A print queue contains…','jobs waiting to be printed','a line of people at a bakery only','quartz crystals','Queue can describe tasks or data waiting to be processed in order.','context'),Q(1,'Which phrase is natural in British English?','wait in a queue','wait in a queue up of','wait queue to a ticket','Wait in a queue is a common expression.','grammar')]);
P('quibble','Origin uncertain; recorded in English in the seventeenth century for a subtle or evasive argument. To quibble is to argue over a minor point instead of the main issue.',C('quibble.s1','通用','The committee stopped quibbling over commas and addressed the budget shortfall.','委员会不再为逗号吹毛求疵，转而处理预算缺口。','quibble over/about + minor detail','动词：纠缠小细节或用细枝末节回避主要问题。','comma dispute distracts from budget.','通用'),M('They quibbled over the budget by focusing on its central shortfall and resolving the main problem.','They addressed the budget shortfall instead of quibbling over minor formatting details.','直接处理核心缺口不是对枝节吹毛求疵。','meaning'),[Q(1,'To quibble over a comma is to…','argue about a minor detail','settle the main financial issue','measure a liquid in quarts','Quibble means raise petty objections about small points.','meaning'),Q(1,'Which phrase is natural?','quibble over a minor detail','quibble a quarrel out','quibble to the quay of','Quibble over/about introduces the detail being disputed.','collocation'),Q(1,'Why might a team be told to stop quibbling?','Its minor objections are distracting from the main problem.','It has solved every major problem already.','It is standing in a queue.','Quibbling can avoid or delay attention to the central issue.','context'),Q(1,'Which is closest to quibble?','raise a petty objection','make a decisive repair','quench someone’s thirst','A quibble is a minor, often evasive objection.','meaning')]);
})();
